function renderCalculator(){if(!result)calculate();return`<div class="hero"><div><h2>Calculateur par système</h2><p>Importez une fiche chantier ou saisissez les informations manuellement.</p></div></div>${calculatorForm()}${uploadCard()}<div class="result-head"><div><b>${esc(result.system.name)}</b><br><small>${esc(result.project||"Projet sans nom")}</small></div><span>${num.format(result.areaM2)} m² / ${num.format(result.areaSqft)} sqft</span><span class="status ${result.summary.missing?"warn":"ok"}">${result.summary.missing?result.summary.missing+" couche(s) à compléter":"Calcul complet"}</span></div><div class="layers">${result.lines.map(layerHTML).join("")}</div><div class="summary"><div class="sum main"><small>Total produits</small><strong>${eur.format(result.summary.totalEUR)}<span>${usd.format(result.summary.totalUSD)}</span></strong></div><div class="sum"><small>Par m²</small><strong>${eur.format(result.summary.perM2EUR)}<span>${usd.format(result.summary.perM2USD)}</span></strong></div><div class="sum"><small>Grille</small><strong>${tierLabel(result.tier)}</strong></div><div class="sum"><small>À compléter</small><strong>${result.summary.missing}</strong></div></div><div class="toolbar"><button class="btn secondary" id="saveSimulation">Enregistrer</button><button class="btn secondary" id="openFloorVisualizer">Visualiser le sol</button><button class="btn dark" onclick="window.print()">PDF client</button><button class="btn primary" id="addCart">Ajouter au panier</button></div>`}
function renderCart(){const t=tenantData(),te=t.cart.reduce((s,x)=>s+x.totalEUR,0),tu=t.cart.reduce((s,x)=>s+x.totalUSD,0),cartSystem=t.cart.find(x=>x.systemId)?.systemId;return`<div class="hero"><div><h2>Commande de produits</h2><p>Les lignes identiques sont regroupées automatiquement.</p></div>${cartSystem?`<button class="btn secondary" id="visualizeCartSystem">Visualiser ce système</button>`:""}</div><div class="card panel">${t.cart.length?`<div class="table-wrap"><table><thead><tr><th>Produit</th><th>Conditionnement</th><th>Qté</th><th>Prix unitaire</th><th>Total</th><th></th></tr></thead><tbody>${t.cart.map((x,i)=>`<tr><td><b>${esc(x.product)}</b></td><td>${esc(x.pack)}</td><td><input data-cart-qty="${i}" type="number" min="0" value="${x.quantity}"></td><td>${eur.format(x.unitPriceEUR)}<br>${usd.format(x.unitPriceUSD)}</td><td><b>${eur.format(x.totalEUR)}<br>${usd.format(x.totalUSD)}</b></td><td><button class="btn danger small" data-cart-delete="${i}">Supprimer</button></td></tr>`).join("")}</tbody></table></div><div class="summary"><div class="sum main"><small>Total</small><strong>${eur.format(te)}<span>${usd.format(tu)}</span></strong></div></div><div class="toolbar"><button class="btn danger" id="clearCart">Vider</button><button class="btn primary" id="sendOrder">Envoyer la commande</button></div>`:'<div class="empty">Panier vide.</div>'}</div>`}
