function ordersTable(orders){return orders.length?`<div class="table-wrap"><table><thead><tr><th>N°</th><th>Date</th><th>Client</th><th>Projet</th><th>Système</th><th>Articles</th><th>Total</th><th>Statut</th><th></th></tr></thead><tbody>${orders.map((o,i)=>`<tr><td><b>${esc(o.id)}</b></td><td>${new Date(o.createdAt).toLocaleString("fr-FR")}</td><td>${esc(o.client)}</td><td>${esc(o.project)}</td><td>${esc(o.systemName||SYSTEMS.find(s=>s.id===o.systemId)?.name||"—")}${o.visualSelection?`<br><small>${esc(o.visualSelection.sampleName)} ${esc(o.visualSelection.code||"")}</small>`:""}</td><td>${o.items.length}</td><td>${eur.format(o.totalEUR)}<br>${usd.format(o.totalUSD)}</td><td><span class="status ok">${esc(o.status)}</span></td><td>${o.systemId?`<button class="btn secondary small" data-visual-order="${i}">Visualiser</button>`:""}</td></tr>`).join("")}</tbody></table></div>`:'<div class="empty">Aucune commande.</div>'}

function visualFamily(system){
  const n=(system?.name||"").toLowerCase();
  if(n.includes("flake"))return"flake";
  if(n.includes("quartz"))return"quartz";
  if(n.includes("reflector")||n.includes("enhancer"))return"reflector";
  if(n.includes("overlay")||n.includes("thin-finish")||n.includes("texture-pave")||n.includes("micro-finish")||n.includes("bace-line"))return"overlay";
  if(n.includes("urethane cement"))return"urethane";
  return"industrial";
}
function visualSystem(){
  const id=visualRuntime.systemId||result?.system?.id||form.systemId||SYSTEMS[0].id;
  return SYSTEMS.find(s=>s.id===id)||SYSTEMS[0];
}
function visualPalettes(){
  const family=visualFamily(visualSystem());
  const list=VISUAL_PALETTES.filter(p=>p.family===family);
  return list.length?list:VISUAL_PALETTES.filter(p=>p.family==="industrial");
}
function visualPalette(){
  const list=visualPalettes();
  let p=list.find(x=>x.id===visualRuntime.paletteId);
  if(!p){p=list[0];visualRuntime.paletteId=p?.id||""}
  return p;
}
function visualSample(){
  const p=visualPalette();
  let s=p?.samples?.find(x=>x.id===visualRuntime.sampleId);
  if(!s){s=p?.samples?.[0];visualRuntime.sampleId=s?.id||""}
  return s;
}
function sourceSystemId(value){
  const t=tenantData();
  if(value==="calc")return result?.system?.id||form.systemId;
  if(value?.startsWith("sim:"))return t.simulations[Number(value.split(":")[1])]?.system?.id||form.systemId;
  if(value?.startsWith("order:"))return t.orders[Number(value.split(":")[1])]?.systemId||form.systemId;
  return visualRuntime.systemId||form.systemId;
}
function visualSourceOptions(){
  const t=tenantData(),out=[`<option value="calc" ${visualRuntime.source==="calc"?"selected":""}>Calculateur actuel — ${esc((result?.system||currentSystem()).name)}</option>`];
  t.simulations.slice(0,8).forEach((s,i)=>out.push(`<option value="sim:${i}" ${visualRuntime.source===`sim:${i}`?"selected":""}>Simulation — ${esc(s.system.name)} · ${num.format(s.areaM2)} m²</option>`));
  t.orders.slice(0,8).forEach((o,i)=>{if(o.systemId)out.push(`<option value="order:${i}" ${visualRuntime.source===`order:${i}`?"selected":""}>Commande ${esc(o.id)} — ${esc(o.systemName||SYSTEMS.find(s=>s.id===o.systemId)?.name||"Système")}</option>`)});
  out.push(`<option value="manual" ${visualRuntime.source==="manual"?"selected":""}>Choix manuel</option>`);
  return out.join("");
}

