async function extractXlsx(buffer){const z=await unzip(buffer),ss=[];if(z["xl/sharedStrings.xml"]){const d=new DOMParser().parseFromString(xmlText(z["xl/sharedStrings.xml"]),"application/xml");d.querySelectorAll("si").forEach(si=>ss.push([...si.querySelectorAll("t")].map(t=>t.textContent).join("")))}let sheetPath="xl/worksheets/sheet1.xml";if(z["xl/workbook.xml"]&&z["xl/_rels/workbook.xml.rels"]){const wb=new DOMParser().parseFromString(xmlText(z["xl/workbook.xml"]),"application/xml"),rels=new DOMParser().parseFromString(xmlText(z["xl/_rels/workbook.xml.rels"]),"application/xml"),s=[...wb.querySelectorAll("sheet")].find(x=>normalizeHeader(x.getAttribute("name"))==="catalogue")||wb.querySelector("sheet"),rid=s?.getAttribute("r:id")||s?.getAttributeNS("http://schemas.openxmlformats.org/officeDocument/2006/relationships","id"),rel=[...rels.querySelectorAll("Relationship")].find(x=>x.getAttribute("Id")===rid);if(rel)sheetPath="xl/"+rel.getAttribute("Target").replace(/^\/?xl\//,"")}const d=new DOMParser().parseFromString(xmlText(z[sheetPath]),"application/xml"),rows=[];d.querySelectorAll("row").forEach(r=>{const vals=[];r.querySelectorAll("c").forEach(c=>{const ref=c.getAttribute("r"),col=ref.match(/[A-Z]+/)[0],idx=[...col].reduce((n,ch)=>n*26+ch.charCodeAt(0)-64,0)-1,v=c.querySelector("v")?.textContent||"",value=c.getAttribute("t")==="s"?ss[Number(v)]:c.getAttribute("t")==="inlineStr"?c.textContent:v;vals[idx]=value});rows.push(vals)});return rows}
async function extractDocx(buffer){const z=await unzip(buffer);if(!z["word/document.xml"])return"";const d=new DOMParser().parseFromString(xmlText(z["word/document.xml"]),"application/xml");return[...d.querySelectorAll("t")].map(x=>x.textContent).join(" ")}
