async function importCatalogFile(file){if(!file)return;let rows=[];try{const ext=file.name.split(".").pop().toLowerCase();if(ext==="xlsx")rows=await extractXlsx(await file.arrayBuffer());else rows=parseDelimited(await file.text());applyImportedCatalog(rows);$("importResult").innerHTML=`<div class="notice" style="margin-top:12px">Import terminé.</div>`}catch(e){$("importResult").innerHTML=`<div class="notice danger" style="margin-top:12px">${esc(e.message)}</div>`}}
function applyImportedCatalog(rows){if(rows.length<2)throw Error("Fichier vide");let hi=rows.findIndex(r=>r.some(x=>normalizeHeader(x).includes("produit conditionnement")));if(hi<0)hi=0;const headers=rows[hi].map(normalizeHeader),idx=n=>headers.findIndex(h=>h.includes(n)),iName=idx("produit conditionnement");if(iName<0)throw Error("Colonne Produit / conditionnement introuvable");const map={recommended:{baseUSD:idx("prix conseille usd"),resaleUSD:idx("prix revente conseille usd"),eur:idx("prix conseille eur")},large:{baseUSD:idx("prix gros chantier usd"),resaleUSD:idx("prix revente gros chantier"),eur:idx("prix gros chantier eur")},premium:{baseUSD:idx("prix premium usd"),resaleUSD:idx("prix revente premium"),eur:idx("prix premium eur")}};let updated=0;for(const r of rows.slice(hi+1)){const name=String(r[iName]||"").trim();if(!name)continue;const row=allCatalog().find(x=>normalizeHeader(x.fullName)===normalizeHeader(name));if(!row)continue;store.catalogOverrides[row.id]={prices:{}};for(const [t,m] of Object.entries(map))store.catalogOverrides[row.id].prices[t]={baseUSD:parseNumber(r[m.baseUSD]),resaleUSD:parseNumber(r[m.resaleUSD]),eur:parseNumber(r[m.eur])};updated++}const carts=refreshAllTenantCarts();refreshCurrentCalculation();saveStore();toast(`${updated} référence(s) mise(s) à jour et ${carts} ligne(s) de panier actualisée(s).`);renderShell()}
async function analyzeFile(file){if(!file)return;let text="";try{const ext=file.name.split(".").pop().toLowerCase(),buf=await file.arrayBuffer();if(ext==="docx")text=await extractDocx(buf);else if(ext==="xlsx")text=(await extractXlsx(buf)).flat().filter(Boolean).join(" ");else if(ext==="pdf")text=extractPdf(buf);else text=new TextDecoder().decode(buf);const a=detectProject(text,file.name);analyzedDocument={...a,fileName:file.name,text:text.slice(0,5000)};tenantData().documents.unshift({...analyzedDocument,createdAt:new Date().toISOString()});saveStore();$("documentAnalysis").innerHTML=`<div class="analysis-card"><h4>Informations détectées</h4><p><b>Système :</b> ${esc(a.systemName||"Non détecté")}<br><b>Surface :</b> ${a.areaM2?num.format(a.areaM2)+" m²":a.areaSqft?num.format(a.areaSqft)+" sqft":"Non détectée"}<br><b>Client :</b> ${esc(a.client||"Non détecté")}<br><b>Projet :</b> ${esc(a.project||"Non détecté")}</p><button class="btn primary" id="applyDocument">Appliquer au calculateur</button>${!text.trim()?'<div class="notice warn" style="margin-top:10px">Le PDF semble scanné ou sans texte exploitable. Une version serveur avec OCR sera nécessaire.</div>':""}</div>`;$("applyDocument").onclick=()=>applyDetected(a)}catch(e){$("documentAnalysis").innerHTML=`<div class="notice danger" style="margin-top:12px">${esc(e.message)}</div>`}}
function detectProject(text,name){const t=(text+" "+name).normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase(),aliases=[["enhancer hd","reh-295"],["reflector enhancer","res-171"],["flake double","dfs-244"],["flake","sfs-327"],["quartz double","dqs-747"],["quartz","sqs-367"],["stout double","dss-742"],["stout","sss-476"],["paramount","paramount"],["urethane cement","uc-neat"],["thin-finish","thin"],["texture-pave","texture"],["micro-finish","micro"],["bace-line","baceline"],["neat","neat"]];let sid="";for(const [a,id] of aliases)if(t.includes(a)){sid=id;break}const m2=t.match(/(\d+(?:[.,]\d+)?)\s*(?:m2|m²|sqm|metres? carres?)/),sf=t.match(/(\d+(?:[.,]\d+)?)\s*(?:sq\s*ft|sqft|square feet)/),line=(label)=>{const r=new RegExp(label+"\\s*[:\\-]\\s*([^\\n\\r]{2,80})","i").exec(text);return r?.[1]?.trim()||""};return{systemId:sid,systemName:SYSTEMS.find(s=>s.id===sid)?.name||"",areaM2:m2?parseNumber(m2[1]):sf?round2(parseNumber(sf[1])/SQFT_PER_M2):0,areaSqft:sf?parseNumber(sf[1]):m2?round2(parseNumber(m2[1])*SQFT_PER_M2):0,client:line("client|societe|company"),project:line("projet|chantier|project|site")}}
function applyDetected(a){if(a.systemId)form.systemId=a.systemId;if(a.areaM2){form.areaM2=a.areaM2;form.areaSqft=a.areaM2*SQFT_PER_M2}if(a.client)form.client=a.client;if(a.project)form.project=a.project;calculate();renderShell();toast("Fiche appliquée au calculateur.")}

/* ================= RENOVO CRETE V9 PATCH ================= */
const V9_ORDER_STATUSES=["Brouillon","Envoyée","En cours de vérification","Modification demandée","Validée","En attente de paiement","Payée","En préparation","Prête à récupérer","Récupérée","Annulée","Refusée"];
const V9_ALLOWED_TRANSITIONS={
  "Brouillon":["Envoyée","Annulée"],
  "Envoyée":["En cours de vérification","Modification demandée","Refusée","Annulée"],
  "En cours de vérification":["Modification demandée","Validée","Refusée","Annulée"],
  "Modification demandée":["Envoyée","En cours de vérification","Annulée"],
  "Validée":["En attente de paiement","Payée","En préparation","Annulée"],
  "En attente de paiement":["Payée","Annulée"],
  "Payée":["En préparation","Annulée"],
  "En préparation":["Prête à récupérer","Annulée"],
  "Prête à récupérer":["Récupérée","Annulée"],
  "Récupérée":[],"Annulée":[],"Refusée":[]
};
let adminCatalogTier="recommended";

function migrateV9(){
  store.settings=store.settings||{};
  if(store.settings.defaultWastePct==null)store.settings.defaultWastePct=10;
  if(!store.settings.supportEmail)store.settings.supportEmail="renovocretebat@gmail.com";
  if(store.settings.supportPhone==null)store.settings.supportPhone="";
  if(!store.settings.defaultPriceTier)store.settings.defaultPriceTier="recommended";
  store.groups=Array.isArray(store.groups)&&store.groups.length?store.groups:[{id:"professionnels",name:"Professionnels",wastePct:null,priceTier:null,catalogAccess:false}];
  store.auditLog=Array.isArray(store.auditLog)?store.auditLog:[];
  store.adminMessages=Array.isArray(store.adminMessages)?store.adminMessages:[];
  for(const a of store.accounts||[]){
    if(a.role==="client"){
      const parts=String(a.contact||"").trim().split(/\s+/).filter(Boolean);
      if(a.firstName==null)a.firstName=parts.shift()||"";
      if(a.lastName==null)a.lastName=parts.join(" ");
      if(!a.category)a.category="Sous-traitant";
      if(!a.groupId)a.groupId="professionnels";
      if(a.catalogAccess==null)a.catalogAccess=false;
      if(a.userWastePct===undefined)a.userWastePct=null;
      if(!a.priceTier)a.priceTier="recommended";
    }
  }
  for(const [id,t] of Object.entries(store.tenants||{})){
    t.messages=Array.isArray(t.messages)?t.messages:[];
    t.notifications=Array.isArray(t.notifications)?t.notifications:[];
    t.documents=Array.isArray(t.documents)?t.documents:[];
    for(const o of t.orders||[]){
      if(!o.paymentStatus)o.paymentStatus=o.status==="Payée"?"Payé":"Non payé";
      if(!o.paymentMode)o.paymentMode="À définir";
      if(!o.statusHistory)o.statusHistory=[{status:o.status||"Envoyée",at:o.createdAt||new Date().toISOString(),author:"Système local"}];
      if(o.invoice===undefined)o.invoice=null;
    }
  }
  const rp=VISUAL_PALETTES.find(p=>p.family==="reflector");
  if(rp)rp.samples=rp.samples.filter(s=>s.kind!=="reference"&&!String(s.id).includes("blue-cloud")&&!String(s.name).toLowerCase().includes("modèle"));
  form.firstName=form.firstName||"";form.lastName=form.lastName||"";
  saveStore();
}
function auditV9(action,resource,oldValue,newValue,note=""){
  store.auditLog=store.auditLog||[];
  store.auditLog.unshift({id:"AUD-"+Date.now()+"-"+Math.random().toString(36).slice(2,7),author:currentAccount()?.email||"Système",action,resource,oldValue,newValue,note,at:new Date().toISOString()});
  if(store.auditLog.length>1000)store.auditLog.length=1000;
}
function groupOf(client){return store.groups.find(g=>g.id===client?.groupId)||null}
function resolveWasteV9(client,includeSimulation=false){
  if(includeSimulation&&isAdmin()&&Number.isFinite(Number(form.wastePct)))return{value:Math.max(0,Number(form.wastePct)||0),source:"Simulation administrateur"};
  if(client?.userWastePct!=null&&client.userWastePct!=="")return{value:Math.max(0,Number(client.userWastePct)||0),source:"Utilisateur"};
  const g=groupOf(client);if(g?.wastePct!=null&&g.wastePct!=="")return{value:Math.max(0,Number(g.wastePct)||0),source:"Groupe"};
  return{value:Math.max(0,Number(store.settings.defaultWastePct)||0),source:"Valeur par défaut"};
}
function tierAdminLabelV9(t){return({recommended:"Tarif de référence",large:"Tarif grand chantier",premium:"Tarif premium"})[t]||"Tarif de référence"}
tierLabel=tierAdminLabelV9;

const calculateV84=calculate;
calculate=function(){if(!isAdmin()&&currentClient())form.wastePct=resolveWasteV9(currentClient()).value;return calculateV84()};

clientNav=function(){const items=[["dashboard","⌂","Tableau de bord"],["calculator","▦","Calculateur"],["visualizer","◈","Visualiseur du sol"],["cart","🛒","Commande produits"],["simulations","▤","Simulations"],["orders","◫","Commandes"]];if(currentClient()?.catalogAccess)items.push(["catalog","▥","Catalogue"]);items.push(["support","✉","Service client"],["faq","?","Questions fréquentes"]);return items};
adminNav=function(){return[["admin-dashboard","⌂","Vue générale"],["clients","👥","Professionnels"],["global-orders","◫","Commandes globales"],["admin-messages","✉","Messagerie"],["admin-catalog","▥","Catalogue & tarifs"],["admin-import","⇅","Imports / exports"],["admin-audit","≡","Journal d’audit"],["admin-settings","⚙","Paramètres"],["faq","?","FAQ"]]};

renderShell=function(){
  const account=currentAccount(),client=currentClient(),clientMode=!!client;
  if(clientMode&&currentView==="catalog"&&!client.catalogAccess)currentView="dashboard";
  const navItems=clientMode?clientNav():adminNav();
  $("nav").innerHTML=navItems.map(([v,i,l])=>`<button data-view="${v}" class="${currentView===v?"active":""}">${i}<span class="label">${l}</span>${v==="cart"?`<span class="count">${tenantData()?.cart?.reduce((s,x)=>s+Number(x.quantity||0),0)||0}</span>`:""}</button>`).join("");
  document.querySelectorAll("[data-view]").forEach(b=>b.onclick=()=>{currentView=b.dataset.view;renderShell()});
  $("tenantCard").innerHTML=client?`<b>${esc(client.company)}</b><small>${esc(client.category||"Professionnel")} · ${esc(client.firstName||"")} ${esc(client.lastName||"")}</small>`:`<b>${esc(account.company)}</b><small>Administration générale</small>`;
  $("modeLabel").textContent=client?(isAdmin()?"Vue administrateur sur client":"Espace client"):"Administration";
  $("backAdminButton").classList.toggle("hidden",!(isAdmin()&&client));
  $("pageTitle").textContent=(clientMode?Object.fromEntries(clientNav().map(x=>[x[0],x[2]])):Object.fromEntries(adminNav().map(x=>[x[0],x[2]])))[currentView]||"RENOVO CRETE";
  renderContent();
};

renderContent=function(){const f={dashboard:renderDashboard,calculator:renderCalculator,visualizer:renderVisualizer,cart:renderCart,simulations:renderSimulations,orders:renderOrders,catalog:renderClientCatalog,support:renderSupportV9,faq:renderFaqV9,"admin-dashboard":renderAdminDashboard,clients:renderClients,"global-orders":renderGlobalOrders,"admin-messages":renderAdminMessagesV9,"admin-catalog":renderAdminCatalog,"admin-import":renderAdminImport,"admin-audit":renderAuditV9,"admin-settings":renderSettingsV9}[currentView];$("content").innerHTML=f?f():"";bindView()};

renderDashboard=function(){const t=tenantData(),c=currentClient(),total=t.orders.reduce((s,o)=>s+Number(o.totalEUR||0),0),open=t.orders.filter(o=>!["Récupérée","Annulée","Refusée"].includes(o.status)).length;return`<div class="hero"><div><h2>Bienvenue ${esc(c.firstName||c.contact||"")}</h2><p>Simulez un système, transmettez une demande de commande et suivez son traitement.</p></div><div class="toolbar" style="margin-top:0"><button class="btn primary" onclick="go('calculator')">Nouvelle simulation</button><button class="btn secondary" onclick="go('visualizer')">Visualiser un sol</button></div></div><div class="grid kpis"><div class="card kpi click-card" onclick="go('simulations')"><small>Simulations</small><strong>${t.simulations.length}</strong><em>Historique personnel</em></div><div class="card kpi click-card" onclick="go('orders')"><small>Commandes</small><strong>${t.orders.length}</strong><em>${open} en cours</em></div><div class="card kpi click-card" onclick="go('cart')"><small>Panier</small><strong>${t.cart.reduce((s,x)=>s+Number(x.quantity||0),0)}</strong><em>Produits sélectionnés</em></div><div class="card kpi click-card" onclick="go('support')"><small>Montant historique</small><strong>${eur.format(total)}</strong><em>Service client disponible</em></div></div><div class="security-banner"><b>Version locale :</b> cette démonstration stocke les données dans le navigateur. Elle ne remplace pas la future version serveur sécurisée et multi-utilisateur.</div><div class="footer-help"><span>${esc(store.settings.supportEmail||"")}</span><button class="btn secondary small" onclick="go('faq')">Questions fréquentes</button></div>`};

renderAdminDashboard=function(){const clients=store.accounts.filter(a=>a.role==="client"),orders=clients.flatMap(c=>(store.tenants[c.id]?.orders||[]).map(o=>({...o,company:c.company}))),unpaid=orders.filter(o=>o.paymentStatus!=="Payé").length,ready=orders.filter(o=>o.status==="Prête à récupérer").length,verify=orders.filter(o=>["Envoyée","En cours de vérification"].includes(o.status)).length,unread=clients.reduce((n,c)=>n+(store.tenants[c.id]?.messages||[]).filter(m=>m.authorRole==="client"&&!m.readByAdmin).length,0);return`<div class="hero"><div><h2>Administration générale</h2><p>Contrôle des professionnels, paramètres techniques, demandes de commande et tarifs.</p></div><button class="btn primary" onclick="go('clients')">Gérer les professionnels</button></div><div class="grid kpis"><div class="card kpi click-card" onclick="go('clients')"><small>Professionnels</small><strong>${clients.length}</strong><em>${clients.filter(x=>x.active).length} actifs</em></div><div class="card kpi click-card" onclick="go('global-orders')"><small>À vérifier</small><strong>${verify}</strong><em>${orders.length} commandes</em></div><div class="card kpi click-card" onclick="go('global-orders')"><small>Impayées</small><strong>${unpaid}</strong><em>${ready} prêtes</em></div><div class="card kpi click-card" onclick="go('admin-messages')"><small>Messages non lus</small><strong>${unread}</strong><em>Messagerie locale</em></div></div><div class="security-banner"><b>Blocage d’architecture :</b> les rôles sont séparés visuellement, mais toutes les données restent présentes dans ce fichier HTML. La confidentialité côté serveur, les paiements, les e-mails, les SMS et les documents privés exigent un backend.</div>`};

calculatorForm=function(){const c=currentClient(),w=resolveWasteV9(c,true);if(!form.firstName)form.firstName=c?.firstName||"";if(!form.lastName)form.lastName=c?.lastName||"";if(!form.client)form.client=c?.company||"";return`<div class="card panel form-card"><div class="form-grid"><div class="field"><label>Nom</label><input id="lastNameInput" value="${esc(form.lastName)}"></div><div class="field"><label>Prénom</label><input id="firstNameInput" value="${esc(form.firstName)}"></div><div class="field span2"><label>Système</label><select id="systemInput">${SYSTEMS.map(s=>`<option value="${s.id}" ${s.id===form.systemId?"selected":""}>${esc(s.name)}</option>`).join("")}</select></div><div class="field"><label>Surface m²</label><input id="m2Input" type="number" min="0" step=".01" value="${round2(form.areaM2)}"></div><div class="field"><label>Surface sqft</label><input id="sqftInput" type="number" min="0" step=".01" value="${round2(form.areaSqft)}"></div>${isAdmin()?`<div class="field"><label>Perte % — administrateur</label><input id="wasteInput" type="number" min="0" max="100" step=".1" value="${form.wastePct}"></div><div class="field"><label>Source</label><input class="readonly" readonly value="${esc(w.source)}"></div>`:""}<div class="field span2"><label>Client / société</label><input id="clientInput" value="${esc(form.client)}"></div><div class="field span2"><label>Projet / chantier</label><input id="projectInput" value="${esc(form.project)}"></div><div class="field span2"><label>Commentaire</label><input id="commentInput" value="${esc(form.comment)}"></div><div class="field"><label>&nbsp;</label><button class="btn primary" id="calculateButton">Calculer les produits</button></div></div>${isAdmin()?`<div class="admin-only-note" style="margin-top:12px">Paramètres internes visibles uniquement dans la vue administrateur. Perte appliquée : <b>${num.format(w.value)} %</b>.</div>`:""}</div>`};

const layerHTMLV84=layerHTML;
layerHTML=function(l){if(isAdmin())return layerHTMLV84(l).replaceAll("Prix conseillé","Tarif de référence");const units=l.pack.rows.reduce((s,r)=>s+Number(r.quantity||0),0);return`<article class="layer"><div class="layer-top"><span class="step">${l.index}</span><div><b>${esc(l.layer.name)}</b><br><small>${esc(l.productName)}</small></div><span class="status ${l.alerts.length?"warn":"ok"}">${l.alerts.length?"Validation requise":"Calculé"}</span><div class="layer-price">${eur.format(l.pack.totalEUR)}<span>${usd.format(l.pack.totalUSD)}</span></div></div><div class="client-layer-grid"><div class="box highlight"><small>Produit proposé</small><strong>${esc(l.productName)}</strong></div><div class="box pack"><small>Quantité finale</small><div class="client-qty">${l.pack.complete?num.format(units)+" unité(s)":"À confirmer"}</div></div><div class="box"><small>Montant de la ligne</small><div class="client-price">${eur.format(l.pack.totalEUR)}</div><span>${usd.format(l.pack.totalUSD)}</span></div></div>${l.alerts.length?`<div class="alerts"><span class="alert">RENOVO CRETE doit compléter ou valider cette ligne avant commande.</span></div>`:""}</article>`};

renderCalculator=function(){if(!result)calculate();const clientSummary=isAdmin()?`<div class="summary"><div class="sum main"><small>Total produits</small><strong>${eur.format(result.summary.totalEUR)}<span>${usd.format(result.summary.totalUSD)}</span></strong></div><div class="sum"><small>Par m²</small><strong>${eur.format(result.summary.perM2EUR)}<span>${usd.format(result.summary.perM2USD)}</span></strong></div><div class="sum"><small>Grille administrative</small><strong>${tierAdminLabelV9(result.tier)}</strong></div><div class="sum"><small>À compléter</small><strong>${result.summary.missing}</strong></div></div>`:`<div class="summary"><div class="sum main"><small>Total estimatif des produits</small><strong>${eur.format(result.summary.totalEUR)}<span>${usd.format(result.summary.totalUSD)}</span></strong></div><div class="sum"><small>Prix estimatif par m²</small><strong>${eur.format(result.summary.perM2EUR)}</strong></div><div class="sum"><small>Lignes calculées</small><strong>${result.lines.length-result.summary.missing}/${result.lines.length}</strong></div><div class="sum"><small>Validation</small><strong>${result.summary.missing?"Requise":"Prête"}</strong></div></div>`;return`<div class="hero"><div><h2>Calculateur par système</h2><p>Renseignez le chantier. Les paramètres techniques internes restent réservés à RENOVO CRETE.</p></div></div>${calculatorForm()}${uploadCard()}<div class="result-head"><div><b>${esc(result.system.name)}</b><br><small>${esc(result.project||"Projet sans nom")}</small></div><span>${num.format(result.areaM2)} m² / ${num.format(result.areaSqft)} sqft</span><span class="status ${result.summary.missing?"warn":"ok"}">${result.summary.missing?"Validation RENOVO CRETE requise":"Calcul complet"}</span></div><div class="layers">${result.lines.map(layerHTML).join("")}</div>${clientSummary}<div class="toolbar"><button class="btn secondary" id="saveSimulation">Enregistrer</button><button class="btn secondary" id="openFloorVisualizer">Visualiser le sol</button><button class="btn dark" onclick="window.print()">PDF client</button><button class="btn primary" id="addCart">Ajouter à la commande</button></div>`};

bindCalculator=function(){const m2=$("m2Input"),sq=$("sqftInput");m2.oninput=()=>sq.value=round2((Number(m2.value)||0)*SQFT_PER_M2);sq.oninput=()=>m2.value=round2((Number(sq.value)||0)/SQFT_PER_M2);$("calculateButton").onclick=()=>{form.systemId=$("systemInput").value;form.areaM2=Number(m2.value)||0;form.areaSqft=form.areaM2*SQFT_PER_M2;form.firstName=$("firstNameInput").value.trim();form.lastName=$("lastNameInput").value.trim();form.wastePct=isAdmin()&&$("wasteInput")?Number($("wasteInput").value)||0:resolveWasteV9(currentClient()).value;form.client=$("clientInput").value;form.project=$("projectInput").value;form.comment=$("commentInput").value;calculate();renderShell()};document.querySelectorAll("[data-product]").forEach(s=>s.onchange=()=>{if(!isAdmin())return;tenantData().productChoices[s.dataset.product]=s.value;tenantData().packChoices[s.dataset.product]="auto";saveStore();calculate();renderShell()});document.querySelectorAll("[data-pack]").forEach(s=>s.onchange=()=>{if(!isAdmin())return;tenantData().packChoices[s.dataset.pack]=s.value;saveStore();calculate();renderShell()});document.querySelectorAll("[data-ov]").forEach(i=>i.onchange=()=>{if(!isAdmin())return;const k=i.dataset.key,o=tenantData().lineOverrides[k]||{};o[i.dataset.ov]=Number(i.value)||0;tenantData().lineOverrides[k]=o;auditV9("Modification paramètre calcul","simulation",null,{key:k,field:i.dataset.ov,value:o[i.dataset.ov]});saveStore();calculate();renderShell()});document.querySelectorAll("[data-duplicate]").forEach(b=>b.onclick=()=>duplicateLine(b.dataset.duplicate));document.querySelectorAll("[data-manual-product]").forEach(b=>b.onclick=()=>openManualProduct(b.dataset.manualProduct));$("saveSimulation").onclick=()=>{tenantData().simulations.unshift(JSON.parse(JSON.stringify({...result,firstName:form.firstName,lastName:form.lastName})));saveStore();toast("Simulation enregistrée.")};$("addCart").onclick=addToCart;$("openFloorVisualizer").onclick=()=>openVisualizerForSystem(result.system.id,"calc");$("documentInput").onchange=e=>analyzeFile(e.target.files[0]);const z=$("uploadZone");z.ondragover=e=>{e.preventDefault();z.classList.add("drag")};z.ondragleave=()=>z.classList.remove("drag");z.ondrop=e=>{e.preventDefault();z.classList.remove("drag");analyzeFile(e.dataTransfer.files[0])}};

renderClientCatalog=function(){if(!currentClient()?.catalogAccess)return`<div class="card panel"><div class="notice danger"><b>Accès non autorisé.</b> Le catalogue n’est pas activé pour ce compte.</div></div>`;const tier=currentClient().priceTier,rows=allCatalog();return`<div class="hero"><div><h2>Catalogue produits</h2><p>Seul le prix attribué à votre compte est affiché.</p></div></div><div class="card panel"><div class="catalog-toolbar"><input id="catalogSearch" placeholder="Rechercher…"><button class="btn secondary" id="downloadClientCatalog">Télécharger Excel</button><button class="btn dark" id="printClientCatalog">PDF</button></div>${catalogTable(rows,tier,false)}</div>`};

renderClients=function(){const cs=store.accounts.filter(a=>a.role==="client");return`<div class="hero"><div><h2>Professionnels et partenaires</h2><p>Gestion des rôles métier, accès catalogue, perte et niveau tarifaire.</p></div><button class="btn primary" id="newClient">Nouveau professionnel</button></div><div class="filter-bar"><input id="clientSearch" placeholder="Rechercher société, nom ou e-mail"><select id="clientCategoryFilter"><option value="">Toutes les catégories</option>${[...new Set(cs.map(c=>c.category||"Autre"))].map(x=>`<option>${esc(x)}</option>`).join("")}</select><select id="clientTierFilter"><option value="">Tous les tarifs</option><option value="recommended">Tarif de référence</option><option value="large">Tarif grand chantier</option><option value="premium">Tarif premium</option></select><select id="clientCatalogFilter"><option value="">Catalogue : tous</option><option value="yes">Accès autorisé</option><option value="no">Accès refusé</option></select></div><div class="client-grid" id="clientGrid">${cs.map(c=>{const t=store.tenants[c.id]||{orders:[],simulations:[]},w=resolveWasteV9(c);return`<div class="card client-card" data-client-card data-search="${esc((c.company+" "+c.firstName+" "+c.lastName+" "+c.email).toLowerCase())}" data-category="${esc(c.category||"")}" data-tier="${c.priceTier}" data-catalog="${c.catalogAccess?"yes":"no"}"><h3>${esc(c.company)}</h3><div class="meta">${esc(c.firstName||"")} ${esc(c.lastName||"")} · ${esc(c.email)}</div><p><span class="status ${c.active?"ok":"error"}">${c.active?"Actif":"Désactivé"}</span> <span class="status warn">${esc(c.category||"Professionnel")}</span></p><div class="compact-grid"><div class="field"><label>Tarif</label><select data-client-tier="${c.id}"><option value="recommended" ${c.priceTier==="recommended"?"selected":""}>Tarif de référence</option><option value="large" ${c.priceTier==="large"?"selected":""}>Tarif grand chantier</option><option value="premium" ${c.priceTier==="premium"?"selected":""}>Tarif premium</option></select></div><div class="field"><label>Perte spécifique %</label><input data-client-waste="${c.id}" type="number" min="0" max="100" step=".1" value="${c.userWastePct??""}" placeholder="${num.format(w.value)} — ${esc(w.source)}"></div><div class="field full"><label>Catégorie</label><select data-client-category="${c.id}">${["Sous-traitant","Installateur","Architecte","Prescripteur","Artisan","Client professionnel","Autre"].map(x=>`<option ${c.category===x?"selected":""}>${x}</option>`).join("")}</select></div><label class="permission-line full"><input data-client-catalog="${c.id}" type="checkbox" ${c.catalogAccess?"checked":""}> Autoriser l’accès au catalogue</label></div><p>${t.simulations?.length||0} simulation(s) · ${t.orders?.length||0} commande(s)</p><div class="toolbar"><button class="btn primary small" data-open-client="${c.id}">Ouvrir l’espace</button><button class="btn secondary small" data-reset-client="${c.id}">Réinitialisation serveur</button><button class="btn ${c.active?"danger":"secondary"} small" data-toggle-client="${c.id}">${c.active?"Désactiver":"Activer"}</button></div></div>`}).join("")}</div>`};

bindClients=function(){const filter=()=>{const q=($("clientSearch")?.value||"").toLowerCase(),cat=$("clientCategoryFilter")?.value||"",tier=$("clientTierFilter")?.value||"",catalog=$("clientCatalogFilter")?.value||"";document.querySelectorAll("[data-client-card]").forEach(card=>card.style.display=(!q||card.dataset.search.includes(q))&&(!cat||card.dataset.category===cat)&&(!tier||card.dataset.tier===tier)&&(!catalog||card.dataset.catalog===catalog)?"":"none")};["clientSearch","clientCategoryFilter","clientTierFilter","clientCatalogFilter"].forEach(id=>$(id)?.addEventListener(id==="clientSearch"?"input":"change",filter));$("newClient").onclick=openNewClient;document.querySelectorAll("[data-client-tier]").forEach(s=>s.onchange=()=>{const c=store.accounts.find(a=>a.id===s.dataset.clientTier),old=c.priceTier;c.priceTier=s.value;auditV9("Changement tarif","utilisateur:"+c.id,old,c.priceTier);const changed=refreshTenantCart(c.id);saveStore();renderShell();toast(`Tarif modifié. ${changed} ligne(s) de panier actualisée(s).`)});document.querySelectorAll("[data-client-waste]").forEach(i=>i.onchange=()=>{const c=store.accounts.find(a=>a.id===i.dataset.clientWaste),old=c.userWastePct;c.userWastePct=i.value===""?null:Number(i.value);auditV9("Changement perte","utilisateur:"+c.id,old,c.userWastePct);saveStore();renderShell()});document.querySelectorAll("[data-client-category]").forEach(s=>s.onchange=()=>{const c=store.accounts.find(a=>a.id===s.dataset.clientCategory),old=c.category;c.category=s.value;auditV9("Changement catégorie","utilisateur:"+c.id,old,c.category);saveStore();renderShell()});document.querySelectorAll("[data-client-catalog]").forEach(i=>i.onchange=()=>{const c=store.accounts.find(a=>a.id===i.dataset.clientCatalog),old=c.catalogAccess;c.catalogAccess=i.checked;auditV9("Permission catalogue","utilisateur:"+c.id,old,c.catalogAccess);saveStore();renderShell()});document.querySelectorAll("[data-open-client]").forEach(b=>b.onclick=()=>{session.impersonatedClientId=b.dataset.openClient;currentView="dashboard";saveStore();renderShell()});document.querySelectorAll("[data-toggle-client]").forEach(b=>b.onclick=()=>{const c=store.accounts.find(a=>a.id===b.dataset.toggleClient),old=c.active;c.active=!c.active;auditV9("Activation compte","utilisateur:"+c.id,old,c.active);saveStore();renderShell()});document.querySelectorAll("[data-reset-client]").forEach(b=>b.onclick=()=>resetClientPassword(b.dataset.resetClient))};

openNewClient=function(){showModal(`<h3>Nouveau professionnel</h3><div class="form-grid"><div class="field"><label>Nom</label><input id="ncLastName"></div><div class="field"><label>Prénom</label><input id="ncFirstName"></div><div class="field span2"><label>Société</label><input id="ncCompany"></div><div class="field span2"><label>E-mail</label><input id="ncEmail" type="email"></div><div class="field span2"><label>Mot de passe local initial</label><input id="ncPassword" type="password"></div><div class="field"><label>Catégorie</label><select id="ncCategory"><option>Sous-traitant</option><option>Installateur</option><option>Architecte</option><option>Prescripteur</option><option>Artisan</option><option>Client professionnel</option><option>Autre</option></select></div><div class="field"><label>Tarif</label><select id="ncTier"><option value="recommended">Tarif de référence</option><option value="large">Tarif grand chantier</option><option value="premium">Tarif premium</option></select></div><label class="permission-line field span2"><input id="ncCatalog" type="checkbox"> Autoriser l’accès au catalogue</label></div><div class="security-banner" style="margin-top:12px">Ce compte est créé uniquement dans ce navigateur. Une authentification serveur est nécessaire pour la production.</div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Annuler</button><button class="btn primary" id="createClientButton">Créer</button></div>`);$("createClientButton").onclick=async()=>{const email=$("ncEmail").value.trim().toLowerCase(),pw=$("ncPassword").value;if(!email||!pw)return toast("E-mail et mot de passe requis.");if(store.accounts.some(a=>a.email.toLowerCase()===email))return toast("E-mail déjà utilisé.");const id="client-"+Date.now(),firstName=$("ncFirstName").value.trim(),lastName=$("ncLastName").value.trim();store.accounts.push({id,role:"client",company:$("ncCompany").value||`${firstName} ${lastName}`.trim()||"Professionnel",contact:`${firstName} ${lastName}`.trim(),firstName,lastName,email,passwordHash:await hashText(pw),active:true,priceTier:$("ncTier").value,category:$("ncCategory").value,groupId:"professionnels",catalogAccess:$("ncCatalog").checked,userWastePct:null,createdAt:new Date().toISOString()});store.tenants[id]={cart:[],simulations:[],orders:[],documents:[],productChoices:{},packChoices:{},lineOverrides:{},customLines:{},visualSelection:null,messages:[],notifications:[]};auditV9("Création compte","utilisateur:"+id,null,{email,category:$("ncCategory").value});saveStore();closeModal();renderShell();toast("Compte local créé.")}};
resetClientPassword=function(id){const c=store.accounts.find(a=>a.id===id);showModal(`<h3>Réinitialisation du mot de passe</h3><div class="notice warn"><b>Fonction bloquée dans la version locale.</b><p>Un vrai parcours exige un serveur, un jeton temporaire, une expiration et un e-mail. Aucun mot de passe n’a été modifié pour ${esc(c?.email||"")}.</p></div><div class="toolbar"><button class="btn primary" onclick="closeModal()">Fermer</button></div>`)};

sendOrder=function(){const t=tenantData();if(!t.cart.length)return;const first=t.cart.find(x=>x.systemId)||{},now=new Date().toISOString(),o={id:"CMD-"+Date.now(),createdAt:now,status:"Envoyée",paymentStatus:"Non payé",paymentMode:"À définir",firstName:form.firstName||currentClient()?.firstName||"",lastName:form.lastName||currentClient()?.lastName||"",client:form.client||currentClient().company,project:form.project||"Projet",systemId:first.systemId||result?.system?.id||form.systemId,systemName:first.systemName||result?.system?.name||currentSystem().name,visualSelection:first.visualSelection||t.visualSelection||null,items:JSON.parse(JSON.stringify(t.cart)),totalEUR:round2(t.cart.reduce((s,x)=>s+x.totalEUR,0)),totalUSD:round2(t.cart.reduce((s,x)=>s+x.totalUSD,0)),statusHistory:[{status:"Envoyée",at:now,author:currentAccount()?.email||"Client"}],invoice:null};t.orders.unshift(o);t.cart=[];auditV9("Création demande de commande","commande:"+o.id,null,{clientId:effectiveClientId(),totalEUR:o.totalEUR});saveStore();go("orders");toast("Demande enregistrée localement. Aucun e-mail ni paiement n’a été déclenché.")};

ordersTable=function(orders){return orders.length?`<div class="table-wrap"><table><thead><tr><th>N°</th><th>Date</th><th>Projet</th><th>Système</th><th>Articles</th><th>Total</th><th>Statut</th><th>Paiement</th><th>Actions</th></tr></thead><tbody>${orders.map((o,i)=>`<tr><td><b>${esc(o.id)}</b></td><td>${new Date(o.createdAt).toLocaleString("fr-FR")}</td><td>${esc(o.project)}</td><td>${esc(o.systemName||SYSTEMS.find(s=>s.id===o.systemId)?.name||"—")}</td><td>${o.items.length}</td><td>${eur.format(o.totalEUR)}<br>${usd.format(o.totalUSD)}</td><td><span class="status ${["Annulée","Refusée"].includes(o.status)?"error":["Récupérée","Payée","Prête à récupérer"].includes(o.status)?"ok":"warn"}">${esc(o.status)}</span></td><td>${esc(o.paymentStatus||"Non payé")}<br><small>${esc(o.paymentMode||"À définir")}</small></td><td><div class="order-actions"><button class="btn secondary small" data-order-detail="${i}">Détail</button>${o.systemId?`<button class="btn secondary small" data-visual-order="${i}">Visualiser</button>`:""}</div></td></tr>`).join("")}</tbody></table></div>`:`<div class="empty">Aucune commande.</div>`};

renderGlobalOrders=function(){const os=store.accounts.filter(a=>a.role==="client").flatMap(c=>(store.tenants[c.id]?.orders||[]).map((o,index)=>({...o,tenantId:c.id,orderIndex:index,clientCompany:c.company})));return`<div class="hero"><div><h2>Commandes globales</h2><p>Vérification, statut et paiement. Les changements sont enregistrés dans le journal local.</p></div></div><div class="card panel">${os.length?`<div class="table-wrap"><table><thead><tr><th>Client</th><th>N°</th><th>Date</th><th>Projet</th><th>Total</th><th>Statut</th><th>Paiement</th><th>Action</th></tr></thead><tbody>${os.map(o=>{const allowed=V9_ALLOWED_TRANSITIONS[o.status]||[];return`<tr><td><b>${esc(o.clientCompany)}</b></td><td>${esc(o.id)}</td><td>${new Date(o.createdAt).toLocaleString("fr-FR")}</td><td>${esc(o.project)}</td><td>${eur.format(o.totalEUR)}</td><td><select class="status-select" data-order-status="${o.tenantId}|${o.orderIndex}"><option selected>${esc(o.status)}</option>${allowed.map(s=>`<option>${s}</option>`).join("")}</select></td><td><select data-order-payment="${o.tenantId}|${o.orderIndex}"><option ${o.paymentStatus==="Non payé"?"selected":""}>Non payé</option><option ${o.paymentStatus==="Payé"?"selected":""}>Payé</option><option ${o.paymentStatus==="Remboursé"?"selected":""}>Remboursé</option></select></td><td><button class="btn secondary small" data-global-order-detail="${o.tenantId}|${o.orderIndex}">Détail</button></td></tr>`}).join("")}</tbody></table></div>`:`<div class="empty">Aucune commande.</div>`}</div>`};

function orderDetailV9(order,admin=false){return`<h3>Commande ${esc(order.id)}</h3><div class="summary"><div class="sum main"><small>Total</small><strong>${eur.format(order.totalEUR)}<span>${usd.format(order.totalUSD)}</span></strong></div><div class="sum"><small>Statut</small><strong>${esc(order.status)}</strong></div><div class="sum"><small>Paiement</small><strong>${esc(order.paymentStatus||"Non payé")}</strong></div><div class="sum"><small>Facture</small><strong>${order.invoice?"Disponible":"Non jointe"}</strong></div></div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Produit</th><th>Conditionnement</th><th>Qté</th><th>Total</th></tr></thead><tbody>${order.items.map(x=>`<tr><td>${esc(x.product)}</td><td>${esc(x.pack)}</td><td>${x.quantity}</td><td>${eur.format(x.totalEUR)}</td></tr>`).join("")}</tbody></table></div><h4>Historique</h4><div class="timeline">${(order.statusHistory||[]).map(h=>`<div class="timeline-item"><b>${esc(h.status)}</b><br><small>${new Date(h.at).toLocaleString("fr-FR")} · ${esc(h.author||"")}</small></div>`).join("")}</div><div class="security-banner" style="margin-top:12px">Paiement en ligne, facture sécurisée, e-mail et SMS : services serveur non configurés dans ce fichier local.</div><div class="toolbar"><button class="btn dark" onclick="window.print()">Imprimer / PDF</button><button class="btn primary" onclick="closeModal()">Fermer</button></div>`}

function renderSupportV9(){const t=tenantData(),msgs=t.messages||[];return`<div class="hero"><div><h2>Service client / Contact</h2><p>Échange local avec RENOVO CRETE. Pour une utilisation réelle entre appareils, une base de données est requise.</p></div></div><div class="grid" style="grid-template-columns:1.25fr .75fr"><div class="card panel"><div class="message-list">${msgs.length?msgs.map(m=>`<div class="message ${m.authorRole==="client"?"mine":""}"><b>${m.authorRole==="client"?"Vous":"RENOVO CRETE"}</b><div>${esc(m.text)}</div><small>${new Date(m.createdAt).toLocaleString("fr-FR")}</small></div>`).join(""):`<div class="empty">Aucun message.</div>`}</div><div class="field" style="margin-top:12px"><label>Votre message</label><textarea id="supportMessage" rows="4" placeholder="Décrivez votre question ou la commande concernée."></textarea></div><button class="btn primary" id="sendSupportMessage" style="margin-top:8px">Envoyer le message</button></div><div class="card panel"><h3 style="margin-top:0">Coordonnées</h3><p><b>E-mail :</b><br>${esc(store.settings.supportEmail||"Non configuré")}</p><p><b>Téléphone :</b><br>${esc(store.settings.supportPhone||"Non configuré")}</p><div class="notice warn">Aucun e-mail ou SMS externe n’est envoyé depuis cette version locale.</div></div></div>`}
function renderAdminMessagesV9(){const clients=store.accounts.filter(a=>a.role==="client"),blocks=clients.map(c=>{const msgs=store.tenants[c.id]?.messages||[];return`<div class="card panel" style="margin-bottom:12px"><h3 style="margin-top:0">${esc(c.company)}</h3><div class="message-list">${msgs.length?msgs.map(m=>`<div class="message ${m.authorRole==="admin"?"mine":""}"><b>${m.authorRole==="admin"?"RENOVO CRETE":esc(c.firstName||c.contact||"Client")}</b><div>${esc(m.text)}</div><small>${new Date(m.createdAt).toLocaleString("fr-FR")}</small></div>`).join(""):`<div class="empty">Aucun message.</div>`}</div><div class="field"><label>Réponse</label><textarea data-admin-reply="${c.id}" rows="2"></textarea></div><button class="btn primary small" data-send-admin-reply="${c.id}" style="margin-top:7px">Répondre</button></div>`}).join("");return`<div class="hero"><div><h2>Messagerie client-administrateur</h2><p>Messagerie fonctionnelle uniquement dans ce navigateur.</p></div></div>${blocks||'<div class="empty">Aucun client.</div>'}`}

