const V91_CATEGORIES=[
  "Professionnel / partenaire","Collaborateur interne","Salarié / employé","Ouvrier / technicien","Commercial","Installateur","Applicateur certifié","Sous-traitant","Artisan","Entreprise générale","Entreprise de bâtiment","Architecte","Architecte d’intérieur","Décorateur / designer","Bureau d’études","Maître d’œuvre","Prescripteur","Promoteur immobilier","Constructeur","Gestionnaire immobilier / syndic","Hôtel / hébergement","Restaurant / CHR","Commerce / retail","Industrie","Collectivité / administration","Établissement scolaire","Client professionnel","Client particulier","Partenaire","Fournisseur","Autre"
];
let editingCartV91=false;
let adminMessageClientIdV91="";
let adminOrderContextV91=null;

function migrateV91(){
  for(const a of store.accounts||[]){
    if(a.role!=="client")continue;
    if(a.phone==null)a.phone="";
    if(!a.category)a.category="Professionnel / partenaire";
    if(a.email==="demo@renovocrete.local"){
      if(a.company==="Sous-traitant Démo")a.company="Professionnel Démo";
      if(a.category==="Sous-traitant")a.category="Installateur";
    }
  }
  for(const t of Object.values(store.tenants||{})){
    for(const o of t.orders||[]){
      if(o.locked==null)o.locked=o.status!=="Brouillon";
      if(!o.adminEdits)o.adminEdits=[];
    }
  }
  document.title="RENOVO CRETE — Professional Portal V9.1";
  const demo=document.querySelector(".demo-box");
  if(demo)demo.innerHTML=demo.innerHTML.replace(/Sous-traitant\s*:/gi,"Professionnel :");
  saveStore();
}
function isProfessionalPortalV91(){return !!currentClient()}
function categoryOptionsV91(selected="",includeBlank=false){
  const values=[...new Set([...V91_CATEGORIES,...store.accounts.filter(a=>a.role==="client").map(a=>a.category).filter(Boolean)])];
  return`${includeBlank?'<option value="">Toutes les catégories</option>':""}${values.map(x=>`<option value="${esc(x)}" ${selected===x?"selected":""}>${esc(x)}</option>`).join("")}`;
}
function clientFullNameV91(c){return`${c?.firstName||""} ${c?.lastName||""}`.trim()||c?.contact||"Professionnel"}

const calculateV90=calculate;
