sendOrder=function(){
  const t=tenantData();if(!t.cart.length)return;
  const first=t.cart.find(x=>x.systemId)||{},now=new Date().toISOString(),o={id:"CMD-"+Date.now(),createdAt:now,validatedAt:now,locked:true,status:"Envoyée",paymentStatus:"Non payé",paymentMode:"À définir",firstName:form.firstName||currentClient()?.firstName||"",lastName:form.lastName||currentClient()?.lastName||"",client:form.client||currentClient()?.company||"Professionnel",project:form.project||"Projet",systemId:first.systemId||result?.system?.id||form.systemId,systemName:first.systemName||result?.system?.name||currentSystem().name,visualSelection:first.visualSelection||t.visualSelection||null,items:JSON.parse(JSON.stringify(t.cart)),totalEUR:round2(t.cart.reduce((s,x)=>s+Number(x.totalEUR||0),0)),totalUSD:round2(t.cart.reduce((s,x)=>s+Number(x.totalUSD||0),0)),statusHistory:[{status:"Envoyée",at:now,author:currentAccount()?.email||"Professionnel"}],adminEdits:[],invoice:null};
  t.orders.unshift(o);t.cart=[];editingCartV91=false;auditV9("Validation et envoi commande","commande:"+o.id,null,{clientId:effectiveClientId(),totalEUR:o.totalEUR,locked:true});saveStore();go("orders");toast("Commande envoyée. Elle ne peut plus être modifiée depuis l’espace professionnel.");
};
