function periodCutoffV91(value){const d=new Date();if(value==="today")d.setHours(0,0,0,0);else if(/^d\d+$/.test(value))d.setDate(d.getDate()-Number(value.slice(1)));else return 0;return d.getTime()}
function latestMessageV91(c){const msgs=store.tenants[c.id]?.messages||[];return msgs.length?msgs[msgs.length-1]:null}
function selectAdminConversationV91(id){
  adminMessageClientIdV91=id;
  const msgs=store.tenants[id]?.messages||[],unread=msgs.filter(m=>m.authorRole==="client"&&!m.readByAdmin);
  if(unread.length){unread.forEach(m=>m.readByAdmin=true);auditV9("Conversation consultée","conversation:"+id,{messagesNonLus:unread.length},{messagesNonLus:0});saveStore()}
  renderShell();
}
function renderAdminMessagesV91(){
  const clients=store.accounts.filter(a=>a.role==="client").sort((a,b)=>(new Date(latestMessageV91(b)?.createdAt||0))-(new Date(latestMessageV91(a)?.createdAt||0)));
  if(!adminMessageClientIdV91||!clients.some(c=>c.id===adminMessageClientIdV91))adminMessageClientIdV91=(clients.find(c=>(store.tenants[c.id]?.messages||[]).some(m=>m.authorRole==="client"&&!m.readByAdmin))||clients[0])?.id||"";
  const active=clients.find(c=>c.id===adminMessageClientIdV91),activeMsgs=active?(store.tenants[active.id]?.messages||[]):[];
  const list=clients.map(c=>{const msgs=store.tenants[c.id]?.messages||[],last=latestMessageV91(c),unread=msgs.filter(m=>m.authorRole==="client"&&!m.readByAdmin).length,search=(c.company+" "+clientFullNameV91(c)+" "+c.email+" "+(c.phone||"")+" "+msgs.map(m=>m.text).join(" ")).toLowerCase();return`<button class="conversation-item ${c.id===adminMessageClientIdV91?"active":""}" data-message-client="${c.id}" data-search="${esc(search)}" data-category="${esc(c.category||"")}" data-latest="${last?new Date(last.createdAt).getTime():0}" data-unread="${unread}"><div class="conversation-top"><b>${esc(clientFullNameV91(c))}</b>${unread?`<span class="count">${unread}</span>`:""}</div><strong>${esc(c.company||"Sans société")}</strong><small>${esc(c.email)}${c.phone?` · ${esc(c.phone)}`:" · Téléphone non renseigné"}</small><p>${last?esc(last.text.slice(0,95)):"Aucun message"}</p><time>${last?new Date(last.createdAt).toLocaleString("fr-FR"):"—"}</time></button>`}).join("");
  const thread=active?`<div class="conversation-header" data-active-search="${esc((active.company+" "+clientFullNameV91(active)+" "+active.email+" "+(active.phone||"")).toLowerCase())}"><div><h3>${esc(clientFullNameV91(active))}</h3><p><b>${esc(active.company||"Sans société")}</b> · ${esc(active.category||"Professionnel / partenaire")}</p></div><div class="contact-lines"><span>${esc(active.email)}</span><span>${esc(active.phone||"Téléphone non renseigné")}</span></div></div><div class="message-list admin-thread">${activeMsgs.length?activeMsgs.map(m=>`<div class="message ${m.authorRole==="admin"?"mine":""}" data-message-bubble data-created="${new Date(m.createdAt).getTime()}" data-search="${esc(String(m.text||"").toLowerCase())}"><b>${m.authorRole==="admin"?"RENOVO CRETE":esc(clientFullNameV91(active))}</b><div>${esc(m.text)}</div><small>${new Date(m.createdAt).toLocaleString("fr-FR")}</small></div>`).join(""):`<div class="empty">Aucun message dans cette conversation.</div>`}</div><div class="field"><label>Réponse à ${esc(clientFullNameV91(active))}</label><textarea id="adminReplyV91" rows="3" placeholder="Rédiger une réponse…"></textarea></div><button class="btn primary" id="sendAdminReplyV91" style="margin-top:8px">Envoyer la réponse</button>`:`<div class="empty">Aucun professionnel enregistré.</div>`;
  return`<div class="hero"><div><h2>Messagerie professionnelle</h2><p>Vue centralisée des échanges, coordonnées complètes, recherche et filtres temporels.</p></div></div><div class="message-filter-bar"><input id="messageSearchV91" placeholder="Rechercher nom, société, e-mail, téléphone ou contenu"><select id="messageCategoryV91">${categoryOptionsV91("",true)}</select><select id="messagePeriodV91"><option value="all">Toutes les dates</option><option value="unread">Messages non lus</option><option value="today">Aujourd’hui</option><option value="d7">7 derniers jours</option><option value="d30">30 derniers jours</option><option value="d90">90 derniers jours</option></select></div><div class="message-workspace"><aside class="conversation-list">${list||'<div class="empty">Aucune conversation.</div>'}</aside><section class="card panel conversation-thread">${thread}</section></div>`;
}
function bindAdminMessagesV91(){
  const apply=()=>{const q=($("messageSearchV91")?.value||"").toLowerCase(),cat=$("messageCategoryV91")?.value||"",period=$("messagePeriodV91")?.value||"all",cutoff=periodCutoffV91(period),activeSearch=document.querySelector("[data-active-search]")?.dataset.activeSearch||"",contactMatch=!q||activeSearch.includes(q);document.querySelectorAll("[data-message-client]").forEach(el=>{const okQ=!q||el.dataset.search.includes(q),okCat=!cat||el.dataset.category===cat,okTime=period==="all"?true:period==="unread"?Number(el.dataset.unread)>0:Number(el.dataset.latest)>=cutoff;el.style.display=okQ&&okCat&&okTime?"":"none"});document.querySelectorAll("[data-message-bubble]").forEach(el=>{const okQ=contactMatch||!q||el.dataset.search.includes(q),okTime=period==="all"||period==="unread"?true:Number(el.dataset.created)>=cutoff;el.style.display=okQ&&okTime?"":"none"})};
  ["messageSearchV91","messageCategoryV91","messagePeriodV91"].forEach(id=>$(id)?.addEventListener(id==="messageSearchV91"?"input":"change",apply));
  document.querySelectorAll("[data-message-client]").forEach(b=>b.onclick=()=>selectAdminConversationV91(b.dataset.messageClient));
  if($("sendAdminReplyV91"))$("sendAdminReplyV91").onclick=()=>{const id=adminMessageClientIdV91,text=$("adminReplyV91").value.trim();if(!id||!text)return;const msg={id:"MSG-"+Date.now(),authorRole:"admin",text,createdAt:new Date().toISOString(),readByAdmin:true,readByClient:false};store.tenants[id].messages.push(msg);auditV9("Réponse administrateur envoyée","conversation:"+id,null,{messageId:msg.id,direction:"administration→professionnel",preview:text.slice(0,120)});saveStore();renderShell()};
}
renderAdminMessagesV9=renderAdminMessagesV91;

function auditTypeV91(x){if(String(x.resource).startsWith("conversation:"))return"conversation";if(String(x.resource).startsWith("commande:"))return"commande";if(String(x.resource).startsWith("catalogue:"))return"catalogue";if(String(x.resource).startsWith("utilisateur:"))return"utilisateur";return"autre"}
