const V92_EXPERTISE_LEVELS=["Débutant","Intermédiaire","Expert"];
const V92_DEFAULT_FAQS=[
  ["Comment utiliser le calculateur ?","Choisissez le système, renseignez la surface, puis lancez le calcul. Les paramètres techniques internes restent réservés à RENOVO CRETE."],
  ["Pourquoi le pourcentage de perte n’apparaît-il pas ?","La perte est un paramètre administratif défini selon le profil, le niveau d’expérience et les contraintes du chantier."],
  ["Puis-je modifier mon nom pour une simulation ?","Oui. Cette modification concerne la simulation en cours et ne modifie pas automatiquement votre profil."],
  ["Comment importer une fiche chantier ?","Utilisez la zone d’import du calculateur. Les informations détectées doivent toujours être vérifiées avant validation."],
  ["Que signifie “validation requise” ?","Une ou plusieurs lignes doivent être contrôlées ou complétées par RENOVO CRETE avant la commande."],
  ["Comment envoyer une commande ?","Ajoutez les produits à votre brouillon, vérifiez le récapitulatif, puis choisissez soit “Valider et envoyer”, soit “Valider, payer et envoyer”."],
  ["Une commande envoyée est-elle immédiatement validée ?","Non. RENOVO CRETE vérifie les produits, les quantités, les disponibilités et les particularités du chantier."],
  ["Pourquoi le total peut-il évoluer ?","Le calcul est une estimation fondée sur les informations saisies. Un produit complémentaire peut être nécessaire selon le support, l’état du chantier ou la finition retenue."],
  ["Comment payer en ligne ?","Lorsqu’un lien de paiement est disponible, il apparaît dans la commande concernée. Vous pouvez aussi recevoir un lien à distance après validation."],
  ["Puis-je payer au dépôt ?","Oui, lorsque cette modalité est proposée par RENOVO CRETE après validation de la commande."],
  ["Comment suivre ma commande ?","Consultez l’onglet Commandes. Le statut évolue jusqu’à “Prête à récupérer”."],
  ["Quand puis-je récupérer ma commande ?","Uniquement lorsque le statut indique “Prête à récupérer”. Le retrait doit être effectué le jour même indiqué par RENOVO CRETE. À défaut, la commande sera annulée, sauf accord préalable."],
  ["Comment obtenir un PDF ?","Utilisez le bouton PDF client ou Imprimer / PDF depuis le détail de la commande."],
  ["Comment contacter RENOVO CRETE ?","Utilisez l’onglet Service client. Vous pouvez rechercher, archiver ou supprimer les messages de votre vue."],
  ["Le visualiseur est-il contractuel ?","Non. Il s’agit d’une simulation commerciale ; le rendu final dépend du support, de l’éclairage, de la préparation et de l’application."],
  ["Mes données sont-elles synchronisées entre appareils ?","Non dans cette version HTML locale. Une base de données sécurisée est nécessaire pour la synchronisation réelle."],
  ["Pourquoi le catalogue est-il absent ?","L’accès au catalogue doit être autorisé par RENOVO CRETE pour votre compte."],
  ["Où se trouve le dépôt ?","Consultez l’onglet Dépôt & itinéraire. L’adresse et les horaires sont configurés par l’administrateur."]
];
