function unreadClientMessagesV92(){return(tenantData()?.messages||[]).filter(m=>m.authorRole==="admin"&&!m.readByClient&&!m.deletedByClient).length}

function migrateV92(){
  store.settings=store.settings||{};
  if(store.settings.depotAddress==null)store.settings.depotAddress="";
  if(store.settings.openingHours==null)store.settings.openingHours="";
  if(store.settings.defaultPaymentLink==null)store.settings.defaultPaymentLink="";
  if(!Array.isArray(store.faqs)||!store.faqs.length)store.faqs=V92_DEFAULT_FAQS.map((x,i)=>({id:`FAQ-${i+1}`,question:x[0],answer:x[1],active:true,order:i+1}));
  const primary=store.accounts.find(a=>a.role==="admin");
  if(primary){
    if(!primary.firstName||["Administrateur","Admin"].includes(primary.firstName))primary.firstName="Olsen";
    if(primary.lastName==null)primary.lastName="";
    if(!primary.displayName)primary.displayName=adminNameV92(primary);
    if(primary.contact==="Administrateur")primary.contact=primary.displayName;
  }
  const reserved=[
    {id:"admin-yonathan",firstName:"Yonathan",lastName:"",displayName:"Yonathan"},
    {id:"admin-jean-jude",firstName:"Jean Jude",lastName:"",displayName:"Jean Jude"}
  ];
  for(const r of reserved)if(!store.accounts.some(a=>a.id===r.id))store.accounts.push({...r,role:"admin",company:"RENOVO CRETE",contact:r.displayName,email:"",passwordHash:"",active:false,pendingSetup:true,createdAt:new Date().toISOString()});
  for(const a of store.accounts||[]){
    if(a.role==="client"&&!V92_EXPERTISE_LEVELS.includes(a.expertiseLevel))a.expertiseLevel="Débutant";
    if(a.role==="admin"){
      if(a.firstName==null)a.firstName="";if(a.lastName==null)a.lastName="";if(!a.displayName)a.displayName=adminNameV92(a);
    }
  }
  for(const t of Object.values(store.tenants||{})){
    t.messages=Array.isArray(t.messages)?t.messages:[];
    for(const m of t.messages){if(m.archivedByClient==null)m.archivedByClient=false;if(m.deletedByClient==null)m.deletedByClient=false}
    for(const o of t.orders||[]){if(o.paymentLink==null)o.paymentLink="";if(o.paymentRequestedAt==null)o.paymentRequestedAt=null}
  }
  document.title="RENOVO CRETE — Portail professionnel V9.2";
  saveStore();
}

