renderCalculator=function(){
  if(!result)calculate();
  const adminMode=!isProfessionalPortalV91()&&isAdmin();
  const summary=adminMode?`<div class="summary"><div class="sum main"><small>Total produits</small><strong>${eur.format(result.summary.totalEUR)}<span>${usd.format(result.summary.totalUSD)}</span></strong></div><div class="sum"><small>Par m²</small><strong>${eur.format(result.summary.perM2EUR)}<span>${usd.format(result.summary.perM2USD)}</span></strong></div><div class="sum"><small>Grille administrative</small><strong>${tierAdminLabelV9(result.tier)}</strong></div><div class="sum"><small>À compléter</small><strong>${result.summary.missing}</strong></div></div>`:`<div class="summary client-summary-v92"><div class="sum main"><small>Total estimatif des produits</small><strong>${eur.format(result.summary.totalEUR)}<span>${usd.format(result.summary.totalUSD)}</span></strong></div><div class="sum"><small>Lignes calculées</small><strong>${result.lines.length-result.summary.missing}/${result.lines.length}</strong></div><div class="sum"><small>Validation</small><strong>${result.summary.missing?"Requise":"Prête"}</strong></div></div>`;
  return`<div class="hero"><div><h2>Calculateur par système</h2><p>Renseignez le chantier. Les paramètres techniques internes restent strictement réservés à RENOVO CRETE.</p></div></div>${calculatorForm()}${uploadCard()}<div class="result-head"><div><b>${esc(result.system.name)}</b><br><small>${esc(result.project||"Projet sans nom")}</small></div><span>${num.format(result.areaM2)} m² / ${num.format(result.areaSqft)} sqft</span><span class="status ${result.summary.missing?"warn":"ok"}">${result.summary.missing?"Validation RENOVO CRETE requise":"Calcul complet"}</span></div><div class="layers">${result.lines.map(layerHTML).join("")}</div>${summary}<div class="toolbar"><button class="btn secondary" id="saveSimulation">Enregistrer</button><button class="btn secondary" id="openFloorVisualizer">Visualiser le sol</button><button class="btn dark" onclick="window.print()">PDF client</button><button class="btn primary" id="addCart">Ajouter à la commande</button></div>`;
};

