function orderEmailDataV93(order){
  const recipient=String(store.settings.supportEmail||'').trim();
  const subject=`Commande ${order.id} — ${order.client||'Professionnel'}`;
  const items=(order.items||[]).map((x,i)=>`${i+1}. ${x.product} — ${x.pack} — Qté ${x.quantity} — ${eur.format(Number(x.totalEUR||0))}`).join('\n');
  const body=`Bonjour RENOVO CRETE,\n\nVeuillez trouver ci-dessous la commande transmise depuis le portail professionnel.\n\nN° de commande : ${order.id}\nClient : ${order.firstName||''} ${order.lastName||''}\nEntreprise : ${order.client||''}\nProjet : ${order.project||''}\nSystème : ${order.systemName||''}\nTotal estimatif : ${eur.format(Number(order.totalEUR||0))}\n\nProduits :\n${items}\n\nCette commande reste soumise au contrôle et à la validation technique de RENOVO CRETE.`;
  const enc=encodeURIComponent;
  return{recipient,subject,body,mailto:`mailto:${enc(recipient)}?subject=${enc(subject)}&body=${enc(body)}`,gmail:`https://mail.google.com/mail/?view=cm&fs=1&to=${enc(recipient)}&su=${enc(subject)}&body=${enc(body)}`,outlook:`https://outlook.live.com/mail/0/deeplink/compose?to=${enc(recipient)}&subject=${enc(subject)}&body=${enc(body)}`};
}
