const orderFiltersV98={
  search:'',
  status:'',
  payment:'',
  period:'today',
  year:'',
  start:'',
  end:''
};

function localDateInputV98(date){
  const d=new Date(date);
  const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');
  return `${y}-${m}-${day}`;
}
function startOfDayV98(value){
  if(!value)return -Infinity;
  const d=new Date(`${value}T00:00:00`);
  return Number.isFinite(d.getTime())?d.getTime():-Infinity;
}
function endOfDayV98(value){
  if(!value)return Infinity;
  const d=new Date(`${value}T23:59:59.999`);
  return Number.isFinite(d.getTime())?d.getTime():Infinity;
}
function orderDateRangeV98(){
  const now=new Date();
  const todayStart=new Date(now.getFullYear(),now.getMonth(),now.getDate()).getTime();
  const todayEnd=todayStart+86400000-1;
  let start=-Infinity,end=Infinity,label='Toutes les dates';

  if(orderFiltersV98.period==='today'){
    start=todayStart;end=todayEnd;label="Aujourd’hui — jour J";
  }else if(orderFiltersV98.period==='yesterday'){
    start=todayStart-86400000;end=todayStart-1;label='Hier';
  }else if(orderFiltersV98.period==='d7'){
    start=todayStart-6*86400000;end=todayEnd;label='7 derniers jours';
  }else if(orderFiltersV98.period==='d30'){
    start=todayStart-29*86400000;end=todayEnd;label='30 derniers jours';
  }else if(orderFiltersV98.period==='d90'){
    start=todayStart-89*86400000;end=todayEnd;label='90 derniers jours';
  }else if(orderFiltersV98.period==='currentYear'){
    start=new Date(now.getFullYear(),0,1).getTime();
    end=new Date(now.getFullYear(),11,31,23,59,59,999).getTime();
    label=`Année ${now.getFullYear()}`;
  }else if(orderFiltersV98.period==='previousYear'){
    start=new Date(now.getFullYear()-1,0,1).getTime();
    end=new Date(now.getFullYear()-1,11,31,23,59,59,999).getTime();
    label=`Année ${now.getFullYear()-1}`;
  }else if(orderFiltersV98.period==='custom'){
    start=startOfDayV98(orderFiltersV98.start);
    end=endOfDayV98(orderFiltersV98.end);
    label=orderFiltersV98.start||orderFiltersV98.end
      ?`${orderFiltersV98.start?new Date(orderFiltersV98.start+'T12:00:00').toLocaleDateString('fr-FR'):'Début libre'} → ${orderFiltersV98.end?new Date(orderFiltersV98.end+'T12:00:00').toLocaleDateString('fr-FR'):'Fin libre'}`
      :'Période personnalisée';
  }

  if(orderFiltersV98.year){
    const year=Number(orderFiltersV98.year);
    const yearStart=new Date(year,0,1).getTime();
    const yearEnd=new Date(year,11,31,23,59,59,999).getTime();
    start=Math.max(start,yearStart);
    end=Math.min(end,yearEnd);
    label=`Année ${year}`;
  }
  return{start,end,label};
}

