/* =============== RENOVO CRETE V10 — CRM CENTRAL, COMMANDES & SYSTÈMES =============== */
const RC_ORDER_STATUSES=['Brouillon','À vérifier','Confirmée','En préparation','En cours de traitement','Expédiée / livrée','Terminée','Annulée','Remboursée partiellement','Remboursée intégralement'];
const RC_PAYMENT_STATUSES=['En attente de paiement','Non payé','Partiellement payé','Payé','Paiement en retard','Remboursement en cours','Partiellement remboursé','Remboursé'];
const RC_PAYMENT_MODES=['Comptant','Paiement en ligne','Virement','Carte','Espèces','Paiement en plusieurs fois'];
let rcOrderView='orders',rcOrderRows=[],rcClientSearch='';

normalizeOrderStatusV96=function(value){const v=String(value||'').trim();if(RC_ORDER_STATUSES.includes(v))return v;return v==='En cours de vérification'||v==='Envoyée'?'À vérifier':v==='Validée / récupérée'||v==='Récupérée'?'Terminée':v==='Prête à être récupérée'?'En préparation':v==='Refusée'?'Annulée':'À vérifier'};
normalizePaymentStatusV96=function(value){const v=String(value||'').trim();if(RC_PAYMENT_STATUSES.includes(v))return v;if(v==='Non payé / en attente de paiement')return'En attente de paiement';return v==='Remboursé'?'Remboursé':v==='Payé'?'Payé':'Non payé'};
orderStatusClassV96=function(value){const s=normalizeOrderStatusV96(value);return['Terminée','Confirmée','Expédiée / livrée'].includes(s)?'st-complete':['Annulée','Remboursée intégralement'].includes(s)?'st-cancelled':['En préparation','En cours de traitement'].includes(s)?'st-ready':'st-review'};
paymentStatusClassV96=function(value){const s=normalizePaymentStatusV96(value);return s==='Payé'?'pay-paid':s==='Remboursé'||s==='Partiellement remboursé'?'pay-refunded':'pay-waiting'};

function rcMoney(v){return eur.format(Number(v||0))}
function rcDate(v){const d=new Date(v);return Number.isFinite(d.getTime())?d.toLocaleDateString('fr-FR'):'—'}
function rcClientName(c){return `${c?.firstName||''} ${c?.lastName||''}`.trim()||c?.contact||'Contact non renseigné'}
function rcAllClients(){return (store.accounts||[]).filter(a=>a.role==='client')}
function rcAllOrders(){const out=[];for(const c of rcAllClients())for(const [index,o] of (store.tenants[c.id]?.orders||[]).entries())out.push({client:c,tenantId:c.id,index,order:o});return out}
function rcOrderPaid(o){return Math.max(0,Number(o.paidAmount??(o.paymentStatus==='Payé'?o.totalEUR:0))||0)}
function rcOrderRefunded(o){return Math.max(0,Number(o.refundedAmount)||0)}
function rcOrderBalance(o){return Math.max(0,Number(o.totalEUR||0)-rcOrderPaid(o)-rcOrderRefunded(o))}
function rcIsOverdue(o){if(!rcOrderBalance(o))return false;const next=(o.installments||[]).find(x=>!x.paid&&x.dueDate);return o.paymentStatus==='Paiement en retard'||(next&&new Date(next.dueDate).getTime()<Date.now())}
function rcClientStats(c){const orders=store.tenants[c.id]?.orders||[],total=orders.reduce((n,o)=>n+Number(o.totalEUR||0),0),paid=orders.reduce((n,o)=>n+rcOrderPaid(o),0),refunded=orders.reduce((n,o)=>n+rcOrderRefunded(o),0),balance=orders.reduce((n,o)=>n+rcOrderBalance(o),0);return{orders,total,paid,refunded,balance,net:Math.max(0,total-refunded),overdue:orders.filter(rcIsOverdue).length,last:orders.slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0]||null}}
function rcThresholds(){store.settings.loyaltyThresholds=store.settings.loyaltyThresholds||{premium:30000,prestige:60000};return store.settings.loyaltyThresholds}
function rcTierFor(total){const t=rcThresholds();return total>=Number(t.prestige||60000)?'Prestige':total>=Number(t.premium||30000)?'Premium':'Standard'}
function rcNextTier(total){const t=rcThresholds();if(total<Number(t.premium))return{label:'Premium',remaining:Number(t.premium)-total,target:Number(t.premium)};if(total<Number(t.prestige))return{label:'Prestige',remaining:Number(t.prestige)-total,target:Number(t.prestige)};return{label:'Prestige',remaining:0,target:Number(t.prestige)}}
function rcPaymentClass(s){return s==='Payé'||s==='Remboursé'?'ok':s==='Paiement en retard'?'danger':'warn'}
function rcStatusClass(s){return ['Terminée','Confirmée','Expédiée / livrée'].includes(s)?'ok':['Annulée','Remboursée intégralement'].includes(s)?'danger':'warn'}
function rcSystemKey(o){const n=o.systemName||SYSTEMS.find(s=>s.id===o.systemId)?.name||'Système non renseigné';return n.replace(/^\w+-\d+\s*[—-]\s*/,'').trim()}
function rcMigrateV10(){
  store.settings=store.settings||{};rcThresholds();store.referrals=Array.isArray(store.referrals)?store.referrals:[];
  ORDER_STATUSES_V96.splice(0,ORDER_STATUSES_V96.length,...RC_ORDER_STATUSES);PAYMENT_STATUSES_V96.splice(0,PAYMENT_STATUSES_V96.length,...RC_PAYMENT_STATUSES);
  for(const c of rcAllClients()){
    c.siret=c.siret||'';c.customerType=c.customerType||'Professionnel';c.acquisitionSource=c.acquisitionSource||'Non renseignée';c.notes=c.notes||'';c.referralCode=c.referralCode||('RC-'+String(c.id).replace(/[^a-z0-9]/gi,'').slice(-6).toUpperCase());c.loyaltyHistory=Array.isArray(c.loyaltyHistory)?c.loyaltyHistory:[];
    const s=rcClientStats(c),tier=rcTierFor(s.net);if(c.loyaltyTier!==tier){c.loyaltyHistory.unshift({tier,at:new Date().toISOString(),total:s.net});c.loyaltyTier=tier}
    for(const o of s.orders){
      if(!RC_ORDER_STATUSES.includes(o.status))o.status=o.status==='En cours de vérification'?'À vérifier':o.status==='Validée / récupérée'?'Terminée':'À vérifier';
      if(!RC_PAYMENT_STATUSES.includes(o.paymentStatus))o.paymentStatus=String(o.paymentStatus||'').includes('Payé')?'Payé':'En attente de paiement';
      if(o.paidAmount==null)o.paidAmount=o.paymentStatus==='Payé'?Number(o.totalEUR||0):0;if(o.refundedAmount==null)o.refundedAmount=0;if(!o.paymentMode)o.paymentMode='Comptant';o.installments=Array.isArray(o.installments)?o.installments:[];o.statusHistory=Array.isArray(o.statusHistory)?o.statusHistory:[];
    }
  }
  document.title='RENOVO CRETE — Mobile & Administration V10';saveStore();
}

function rcKpi(label,value,detail,view,cls=''){return`<div class="rc-v10-kpi ${cls}" onclick="go('${view}')"><small>${esc(label)}</small><strong>${esc(String(value))}</strong><em>${esc(detail)}</em></div>`}
renderAdminDashboard=function(){const clients=rcAllClients(),rows=rcAllOrders(),active=clients.filter(c=>c.active).length,review=rows.filter(x=>x.order.status==='À vérifier').length,pending=rows.filter(x=>rcOrderBalance(x.order)>0&&!rcIsOverdue(x.order)).length,late=rows.filter(x=>rcIsOverdue(x.order)).length,unread=unreadAdminMessagesV92(),paid=rows.reduce((n,x)=>n+rcOrderPaid(x.order),0),balance=rows.reduce((n,x)=>n+rcOrderBalance(x.order),0),changed=clients.filter(c=>c.loyaltyHistory?.[0]&&!c.loyaltyHistory[0].adminRead).length,recent=rows.sort((a,b)=>new Date(b.order.createdAt)-new Date(a.order.createdAt)).slice(0,6);return`<div class="rc-v10-hero"><h2>Pilotage RENOVO CRETE</h2><p>Vue centrale des professionnels, commandes, paiements, soldes, fidélité et échanges.</p><div class="rc-v10-actions"><button class="btn primary" onclick="go('global-orders')">Traiter les commandes</button><button class="btn secondary" onclick="go('clients')">Ouvrir le CRM client</button></div></div><div class="rc-v10-kpis">${rcKpi('Professionnels actifs',active,`${clients.length} comptes`,'clients')}${rcKpi('Commandes à vérifier',review,'Action administrative','global-orders')}${rcKpi('Paiements en attente',pending,`${rcMoney(balance)} à encaisser`,'receivables')}${rcKpi('Paiements en retard',late,'Relance prioritaire','receivables','danger')}${rcKpi('Messages non lus',unread,'Accéder aux échanges','admin-messages')}${rcKpi('CA encaissé',rcMoney(paid),'Paiements enregistrés','portfolio')}${rcKpi('Changements de catégorie',changed,'Standard · Premium · Prestige','loyalty')}${rcKpi('Bibliothèque systèmes',3,'Fiches techniques illustrées','system-library')}</div><div class="rc-v10-grid"><section class="rc-v10-panel"><h3>Dernières commandes</h3><div class="rc-v10-mini-list">${recent.length?recent.map(x=>`<div><span><b>${esc(x.order.id)}</b><br><small>${esc(x.client.company)} · ${esc(rcSystemKey(x.order))}</small></span><span><b>${rcMoney(x.order.totalEUR)}</b><br><small>${esc(x.order.status)}</small></span></div>`).join(''):'<div class="rc-v10-empty">Aucune commande.</div>'}</div></section><section class="rc-v10-panel"><h3>Priorités financières</h3><div class="rc-v10-mini-list"><div><span>Montant encaissé</span><b class="rc-v10-money">${rcMoney(paid)}</b></div><div><span>Reste à encaisser</span><b class="rc-v10-danger">${rcMoney(balance)}</b></div><div><span>Clients débiteurs</span><b>${clients.filter(c=>rcClientStats(c).balance>0).length}</b></div><div><span>Échéances en retard</span><b>${late}</b></div></div><button class="btn primary" onclick="go('receivables')" style="margin-top:12px">Gérer les encaissements</button></section></div>`};

function rcClientCard(c){const s=rcClientStats(c),tier=rcTierFor(s.net),next=rcNextTier(s.net),progress=Math.min(100,next.target?s.net/next.target*100:100);return`<article class="rc-v10-client" data-rc-client data-search="${esc((c.company+' '+rcClientName(c)+' '+c.email+' '+(c.phone||'')+' '+(c.siret||'')).toLowerCase())}" data-tier="${tier}" data-debt="${s.balance>0?'yes':'no'}"><div style="display:flex;justify-content:space-between;gap:8px"><div><h3>${esc(c.company||'Sans société')}</h3><small>${esc(rcClientName(c))}</small></div><span class="rc-v10-tier">${tier}</span></div><p>${esc(c.email||'E-mail non renseigné')}<br>${esc(c.phone||'Téléphone non renseigné')} · SIRET ${esc(c.siret||'non renseigné')}</p><div class="rc-v10-mini-list"><div><span>Total achats</span><b>${rcMoney(s.net)}</b></div><div><span>Encaissé</span><b class="rc-v10-money">${rcMoney(s.paid)}</b></div><div><span>Solde dû</span><b class="${s.balance?'rc-v10-danger':''}">${rcMoney(s.balance)}</b></div></div><div class="rc-v10-progress"><span style="width:${progress}%"></span></div><small>${next.remaining?`${rcMoney(next.remaining)} avant ${next.label}`:'Palier Prestige atteint'}</small><div class="toolbar"><button class="btn primary small" data-rc-client-sheet="${c.id}">Voir la fiche</button><button class="btn secondary small" data-open-client="${c.id}">Ouvrir l’espace</button></div></article>`}
renderClients=function(){const cs=rcAllClients();return`<div class="rc-v10-hero"><h2>Clients & professionnels</h2><p>Une fiche unique centralise l’identité, l’entreprise, les commandes, paiements, soldes, fidélité, parrainage et historique.</p><div class="rc-v10-actions"><button class="btn primary" id="newClient">Nouveau professionnel</button></div></div><div class="rc-v10-filter"><div class="field"><label>Recherche</label><input id="rcClientSearch" placeholder="Nom, société, e-mail, téléphone, SIRET"></div><div class="field"><label>Catégorie fidélité</label><select id="rcClientTier"><option value="">Toutes</option><option>Standard</option><option>Premium</option><option>Prestige</option></select></div><div class="field"><label>Solde</label><select id="rcClientDebt"><option value="">Tous</option><option value="yes">Solde dû</option><option value="no">À jour</option></select></div></div><div class="rc-v10-client-grid">${cs.map(rcClientCard).join('')||'<div class="rc-v10-empty">Aucun client.</div>'}</div>`};
function rcClientSheet(id){const c=store.accounts.find(a=>a.id===id);if(!c)return;const s=rcClientStats(c),tier=rcTierFor(s.net),history=s.orders.slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));showModal(`<div class="rc-v10-drawer"><div style="display:flex;justify-content:space-between;gap:10px"><div><h3>${esc(c.company)}</h3><p>${esc(rcClientName(c))} · ${esc(c.customerType)}</p></div><span class="rc-v10-tier">${tier}</span></div><div class="rc-v10-grid"><div class="rc-v10-panel"><h3>Identité & entreprise</h3><p><b>E-mail :</b> ${esc(c.email||'—')}<br><b>Téléphone :</b> ${esc(c.phone||'—')}<br><b>SIRET :</b> ${esc(c.siret||'—')}<br><b>Source :</b> ${esc(c.acquisitionSource||'—')}<br><b>Code parrainage :</b> ${esc(c.referralCode)}</p></div><div class="rc-v10-panel"><h3>Valeur client</h3><p><b>Total achats :</b> ${rcMoney(s.net)}<br><b>Encaissé :</b> ${rcMoney(s.paid)}<br><b>Remboursé :</b> ${rcMoney(s.refunded)}<br><b>Solde restant :</b> <span class="rc-v10-danger">${rcMoney(s.balance)}</span><br><b>Ancienneté :</b> depuis ${rcDate(c.createdAt)}</p></div></div><h3>Historique des commandes</h3><div class="table-wrap"><table class="rc-v10-table"><thead><tr><th>Commande</th><th>Date</th><th>Système</th><th>Total</th><th>Encaissé</th><th>Solde</th></tr></thead><tbody>${history.map(o=>`<tr><td>${esc(o.id)}</td><td>${rcDate(o.createdAt)}</td><td>${esc(rcSystemKey(o))}</td><td>${rcMoney(o.totalEUR)}</td><td>${rcMoney(rcOrderPaid(o))}</td><td>${rcMoney(rcOrderBalance(o))}</td></tr>`).join('')||'<tr><td colspan="6">Aucune commande.</td></tr>'}</tbody></table></div><div class="toolbar"><a class="btn secondary" href="mailto:${encodeURIComponent(c.email||'')}">Envoyer un e-mail</a><a class="btn secondary" href="tel:${esc(c.phone||'')}">Appeler</a><button class="btn primary" onclick="closeModal()">Fermer</button></div></div>`)}

function rcOrderCard(x){const o=x.order,c=x.client,balance=rcOrderBalance(o),paid=rcOrderPaid(o),late=rcIsOverdue(o);return`<article class="rc-v10-order" data-rc-order data-search="${esc((o.id+' '+c.company+' '+rcClientName(c)+' '+o.project+' '+rcSystemKey(o)+' '+(o.items||[]).map(i=>i.product).join(' ')).toLowerCase())}" data-system="${esc(rcSystemKey(o))}" data-status="${esc(o.status)}" data-payment="${esc(o.paymentStatus)}" data-mode="${esc(o.paymentMode||'Comptant')}" data-total="${Number(o.totalEUR||0)}" data-balance="${balance}" data-time="${new Date(o.createdAt).getTime()}" data-overdue="${late?'yes':'no'}"><div class="rc-v10-order-top"><div><h3>${esc(o.id)} · ${esc(c.company)}</h3><p>${esc(rcClientName(c))} · ${rcDate(o.createdAt)} · ${esc(o.project||'Projet non renseigné')}</p></div><div><span class="rc-v10-chip ${rcStatusClass(o.status)}">${esc(o.status)}</span> <span class="rc-v10-chip ${rcPaymentClass(o.paymentStatus)}">${esc(o.paymentStatus)}</span></div></div><div class="rc-v10-order-meta"><div class="rc-v10-stat"><small>Système</small><b>${esc(rcSystemKey(o))}</b></div><div class="rc-v10-stat"><small>Total</small><b>${rcMoney(o.totalEUR)}</b></div><div class="rc-v10-stat"><small>Encaissé</small><b>${rcMoney(paid)}</b></div><div class="rc-v10-stat"><small>Remboursé</small><b>${rcMoney(rcOrderRefunded(o))}</b></div><div class="rc-v10-stat"><small>Solde</small><b class="${balance?'rc-v10-danger':''}">${rcMoney(balance)}</b></div><div class="rc-v10-stat"><small>Mode</small><b>${esc(o.paymentMode||'Comptant')}</b></div></div><div class="toolbar"><button class="btn secondary small" data-rc-client-sheet="${c.id}">Voir le client</button><button class="btn secondary small" data-rc-order-detail="${x.tenantId}|${x.index}">Détail</button><select data-rc-order-status="${x.tenantId}|${x.index}">${RC_ORDER_STATUSES.map(s=>`<option ${o.status===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select data-rc-payment-status="${x.tenantId}|${x.index}">${RC_PAYMENT_STATUSES.map(s=>`<option ${o.paymentStatus===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div></article>`}
function rcGroupedOrders(rows){const groups={};for(const x of rows){const k=rcSystemKey(x.order);(groups[k]||(groups[k]=[])).push(x)}return Object.entries(groups).sort((a,b)=>b[1].length-a[1].length).map(([name,list])=>{const total=list.reduce((n,x)=>n+Number(x.order.totalEUR||0),0),paid=list.reduce((n,x)=>n+rcOrderPaid(x.order),0),balance=list.reduce((n,x)=>n+rcOrderBalance(x.order),0),products=list.reduce((n,x)=>n+(x.order.items||[]).reduce((s,i)=>s+Number(i.quantity||0),0),0);return`<article class="rc-v10-group-card"><header><div><h3>${esc(name)}</h3><small>${list.length} commande(s) · ${products} produit(s)</small></div><span class="rc-v10-tier">${rcMoney(total)}</span></header><div class="rc-v10-order-meta"><div class="rc-v10-stat"><small>Montant cumulé</small><b>${rcMoney(total)}</b></div><div class="rc-v10-stat"><small>Encaissé</small><b>${rcMoney(paid)}</b></div><div class="rc-v10-stat"><small>Solde restant</small><b>${rcMoney(balance)}</b></div></div><button class="btn secondary small" data-rc-filter-system="${esc(name)}" style="margin-top:10px">Voir les commandes du groupe</button></article>`}).join('')}
renderGlobalOrders=function(){rcOrderRows=rcAllOrders().sort((a,b)=>new Date(b.order.createdAt)-new Date(a.order.createdAt));const systems=[...new Set(rcOrderRows.map(x=>rcSystemKey(x.order)))].sort(),total=rcOrderRows.reduce((n,x)=>n+Number(x.order.totalEUR||0),0),paid=rcOrderRows.reduce((n,x)=>n+rcOrderPaid(x.order),0),balance=rcOrderRows.reduce((n,x)=>n+rcOrderBalance(x.order),0);return`<div class="rc-v10-hero"><h2>Commandes globales</h2><p>Vue classique ou regroupée par système, avec statuts de commande et de paiement indépendants.</p></div><div class="rc-v10-kpis">${rcKpi('Commandes',rcOrderRows.length,'Résultat avant filtres','global-orders')}${rcKpi('Montant total',rcMoney(total),'Toutes commandes','global-orders')}${rcKpi('Encaissé',rcMoney(paid),'Paiements validés','receivables')}${rcKpi('Solde restant',rcMoney(balance),'À encaisser','receivables')}</div><div class="rc-v10-panel"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:12px"><div class="rc-v10-switch"><button data-rc-order-view="orders" class="${rcOrderView==='orders'?'active':''}">Par commande</button><button data-rc-order-view="systems" class="${rcOrderView==='systems'?'active':''}">Par système</button></div><div class="toolbar" style="margin:0"><button class="btn secondary small" id="rcSaveOrderView">Enregistrer la vue</button><button class="btn secondary small" id="rcExportOrders">Exporter CSV</button><button class="btn secondary small" id="rcResetOrders">Réinitialiser</button></div></div><div class="rc-v10-filter"><div class="field"><label>Recherche</label><input id="rcOrderSearch" placeholder="Référence, client, entreprise, produit"></div><div class="field"><label>Système</label><select id="rcOrderSystem"><option value="">Tous</option>${systems.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Commande</label><select id="rcOrderStatus"><option value="">Tous les statuts</option>${RC_ORDER_STATUSES.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Paiement</label><select id="rcPaymentStatus"><option value="">Tous les paiements</option>${RC_PAYMENT_STATUSES.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Mode</label><select id="rcPaymentMode"><option value="">Tous</option>${RC_PAYMENT_MODES.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Période</label><select id="rcOrderPeriod"><option value="all">Toutes dates</option><option value="today">Aujourd’hui</option><option value="d7">7 jours</option><option value="d30">30 jours</option><option value="custom">Dates personnalisées</option></select></div><div class="field"><label>Du</label><input id="rcOrderStart" type="date"></div><div class="field"><label>Au</label><input id="rcOrderEnd" type="date"></div><div class="field"><label>Montant min.</label><input id="rcOrderMin" type="number" min="0"></div><div class="field"><label>Solde</label><select id="rcOrderBalance"><option value="">Tous</option><option value="yes">Solde restant</option><option value="late">En retard</option><option value="no">Soldé</option></select></div></div><div id="rcOrderResults"><div class="${rcOrderView==='systems'?'rc-v10-group':'rc-v10-order-list'}">${rcOrderView==='systems'?rcGroupedOrders(rcOrderRows):rcOrderRows.map(rcOrderCard).join('')}</div></div></div>`};

function rcShowOrderDetail(tid,index){const o=store.tenants[tid]?.orders?.[index],c=store.accounts.find(a=>a.id===tid);if(!o||!c)return;const installments=o.installments||[];showModal(`<h3>${esc(o.id)}</h3><p>${esc(c.company)} · ${esc(rcClientName(c))} · ${esc(rcSystemKey(o))}</p><div class="rc-v10-grid"><div class="rc-v10-panel"><h3>Commande</h3><p>Total : <b>${rcMoney(o.totalEUR)}</b><br>Encaissé : <b>${rcMoney(rcOrderPaid(o))}</b><br>Remboursé : <b>${rcMoney(rcOrderRefunded(o))}</b><br>Solde : <b class="rc-v10-danger">${rcMoney(rcOrderBalance(o))}</b></p></div><div class="rc-v10-panel"><h3>Plan de paiement</h3><div class="rc-v10-mini-list">${installments.map((x,i)=>`<div><span>Échéance ${i+1} · ${rcDate(x.dueDate)}</span><b>${rcMoney(x.amount)} · ${x.paid?'Payée':'À payer'}</b></div>`).join('')||'<div>Aucune échéance configurée.</div>'}</div></div></div><div class="form-grid" style="margin-top:14px"><div class="field span2"><label>Montant encaissé</label><input id="rcPaidEdit" type="number" min="0" step=".01" value="${rcOrderPaid(o)}"></div><div class="field span2"><label>Montant remboursé</label><input id="rcRefundEdit" type="number" min="0" step=".01" value="${rcOrderRefunded(o)}"></div><div class="field span2"><label>Mode de paiement</label><select id="rcModeEdit">${RC_PAYMENT_MODES.map(m=>`<option ${o.paymentMode===m?'selected':''}>${esc(m)}</option>`).join('')}</select></div></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">Fermer</button><button class="btn primary" id="rcSavePayment">Enregistrer le paiement</button></div>`);$('rcSavePayment').onclick=()=>{const old={paid:o.paidAmount,refund:o.refundedAmount,mode:o.paymentMode};o.paidAmount=Math.min(Number(o.totalEUR||0),Math.max(0,Number($('rcPaidEdit').value)||0));o.refundedAmount=Math.max(0,Number($('rcRefundEdit').value)||0);o.paymentMode=$('rcModeEdit').value;o.paymentStatus=rcOrderBalance(o)<=0?'Payé':o.paidAmount>0?'Partiellement payé':'Non payé';auditV9('Mise à jour encaissement','commande:'+o.id,old,{paid:o.paidAmount,refund:o.refundedAmount,mode:o.paymentMode});rcMigrateV10();closeModal();renderShell();toast('Paiement mis à jour.')}}

function renderReceivablesV10(){const rows=rcAllOrders().filter(x=>rcOrderBalance(x.order)>0).sort((a,b)=>Number(rcIsOverdue(b.order))-Number(rcIsOverdue(a.order))||rcOrderBalance(b.order)-rcOrderBalance(a.order)),total=rows.reduce((n,x)=>n+rcOrderBalance(x.order),0);return`<div class="rc-v10-hero"><h2>Impayés & paiements échelonnés</h2><p>Liste priorisée des sommes restant à encaisser, échéances proches et retards.</p></div><div class="rc-v10-kpis">${rcKpi('Clients débiteurs',new Set(rows.map(x=>x.tenantId)).size,'Fiches clients concernées','clients')}${rcKpi('Solde total',rcMoney(total),'Reste à encaisser','receivables')}${rcKpi('Paiements en retard',rows.filter(x=>rcIsOverdue(x.order)).length,'Relances prioritaires','receivables')}${rcKpi('Plans échelonnés',rows.filter(x=>x.order.installments?.length).length,'Échéanciers actifs','receivables')}</div><div class="rc-v10-order-list">${rows.map(rcOrderCard).join('')||'<div class="rc-v10-panel rc-v10-empty">Aucun solde restant.</div>'}</div>`}
function renderPortfolioV10(){const clients=rcAllClients().map(c=>({c,s:rcClientStats(c)})).sort((a,b)=>b.s.net-a.s.net),total=clients.reduce((n,x)=>n+x.s.net,0),paid=clients.reduce((n,x)=>n+x.s.paid,0);return`<div class="rc-v10-hero"><h2>Portefeuille client</h2><p>Analyse de la valeur, des encaissements, des soldes et de la concentration commerciale.</p></div><div class="rc-v10-kpis">${rcKpi('Valeur des achats',rcMoney(total),'Hors remboursements','portfolio')}${rcKpi('CA encaissé',rcMoney(paid),'Paiements validés','portfolio')}${rcKpi('Clients actifs',clients.filter(x=>x.c.active).length,'Comptes autorisés','clients')}${rcKpi('Client principal',clients[0]?.c.company||'—',clients[0]?rcMoney(clients[0].s.net):'Aucun achat','clients')}</div><div class="rc-v10-panel"><div class="table-wrap"><table class="rc-v10-table"><thead><tr><th>Rang</th><th>Client</th><th>Catégorie</th><th>Commandes</th><th>Total achats</th><th>Encaissé</th><th>Solde</th></tr></thead><tbody>${clients.map((x,i)=>`<tr><td>${i+1}</td><td><button class="btn secondary small" data-rc-client-sheet="${x.c.id}">${esc(x.c.company)}</button></td><td>${rcTierFor(x.s.net)}</td><td>${x.s.orders.length}</td><td>${rcMoney(x.s.net)}</td><td>${rcMoney(x.s.paid)}</td><td>${rcMoney(x.s.balance)}</td></tr>`).join('')}</tbody></table></div></div>`}
function renderLoyaltyV10(){const t=rcThresholds(),clients=rcAllClients().map(c=>({c,s:rcClientStats(c)}));return`<div class="rc-v10-hero"><h2>Fidélité & catégories clients</h2><p>Classement automatique selon le total d’achats produits : Standard, Premium et Prestige.</p></div><div class="rc-v10-panel"><h3>Seuils administrables</h3><div class="form-grid"><div class="field span2"><label>Premium à partir de</label><input id="rcPremiumThreshold" type="number" value="${t.premium}"></div><div class="field span2"><label>Prestige à partir de</label><input id="rcPrestigeThreshold" type="number" value="${t.prestige}"></div><div class="field span2"><label>&nbsp;</label><button class="btn primary" id="rcSaveThresholds">Enregistrer</button></div></div></div><div class="rc-v10-client-grid" style="margin-top:14px">${clients.map(x=>rcClientCard(x.c)).join('')}</div>`}
function renderReferralsV10(){const clients=rcAllClients(),refs=store.referrals||[];return`<div class="rc-v10-hero"><h2>Parrainage</h2><p>Suivi du parrain, du filleul, du statut et de la récompense associée.</p></div><div class="rc-v10-panel"><div class="form-grid"><div class="field span2"><label>Parrain</label><select id="rcSponsor"><option value="">Sélectionner</option>${clients.map(c=>`<option value="${c.id}">${esc(c.company)}</option>`).join('')}</select></div><div class="field span2"><label>Filleul</label><select id="rcReferral"><option value="">Sélectionner</option>${clients.map(c=>`<option value="${c.id}">${esc(c.company)}</option>`).join('')}</select></div><div class="field"><label>Récompense</label><input id="rcReward" placeholder="Ex. remise 5 %"></div><div class="field"><label>&nbsp;</label><button class="btn primary" id="rcAddReferral">Ajouter</button></div></div></div><div class="rc-v10-panel" style="margin-top:14px"><div class="table-wrap"><table class="rc-v10-table"><thead><tr><th>Parrain</th><th>Filleul</th><th>Date</th><th>Statut</th><th>Récompense</th></tr></thead><tbody>${refs.map(r=>{const a=clients.find(c=>c.id===r.sponsorId),b=clients.find(c=>c.id===r.referralId);return`<tr><td>${esc(a?.company||'—')}</td><td>${esc(b?.company||'—')}</td><td>${rcDate(r.createdAt)}</td><td>${esc(r.status)}</td><td>${esc(r.reward||'—')}</td></tr>`}).join('')||'<tr><td colspan="5">Aucun parrainage.</td></tr>'}</tbody></table></div></div>`}

