function renderSystemLibraryV10(){return`<div class="rc-v10-hero"><h2>Bibliothèque des systèmes</h2><p>Fiches illustrées intégrées au calculateur et à la prescription technique RENOVO CRETE.</p></div><div class="rc-v10-note"><b>Validation technique obligatoire.</b> La préparation mécanique, l’humidité, les fissures, les pentes, l’exposition UV, les produits réellement disponibles et les fiches techniques doivent être vérifiés avant devis ou application.</div><div class="rc-v10-system-grid" style="margin-top:14px">${RC_SYSTEM_CARDS.map(s=>`<article class="rc-v10-system"><img src="${s.image}" alt="Schéma technique ${esc(s.title)}"><div class="rc-v10-system-body"><h3>${esc(s.title)}</h3><p>${esc(s.usage)}</p><div class="rc-v10-layers">${s.layers.map(l=>`<div class="rc-v10-layer">${esc(l)}</div>`).join('')}</div><div class="rc-v10-note" style="margin-top:10px">${esc(s.note)}</div><div class="toolbar"><button class="btn primary small" data-rc-use-system="${s.id}">Utiliser dans le calculateur</button><button class="btn secondary small" data-rc-system-image="${s.image}">Agrandir</button></div></div></article>`).join('')}</div>`}

function rcFilterOrders(){const q=($('rcOrderSearch')?.value||'').toLowerCase(),system=$('rcOrderSystem')?.value||'',status=$('rcOrderStatus')?.value||'',payment=$('rcPaymentStatus')?.value||'',mode=$('rcPaymentMode')?.value||'',period=$('rcOrderPeriod')?.value||'all',min=Number($('rcOrderMin')?.value||0),balance=$('rcOrderBalance')?.value||'',startVal=$('rcOrderStart')?.value,endVal=$('rcOrderEnd')?.value;let start=-Infinity,end=Infinity;if(period==='today'){const d=new Date();d.setHours(0,0,0,0);start=d.getTime();end=start+86400000-1}else if(period==='d7')start=Date.now()-7*86400000;else if(period==='d30')start=Date.now()-30*86400000;else if(period==='custom'){if(startVal)start=new Date(startVal+'T00:00:00').getTime();if(endVal)end=new Date(endVal+'T23:59:59').getTime()}return rcOrderRows.filter(x=>{const o=x.order,t=new Date(o.createdAt).getTime(),bal=rcOrderBalance(o);return(!q||(o.id+' '+x.client.company+' '+rcClientName(x.client)+' '+o.project+' '+rcSystemKey(o)+' '+(o.items||[]).map(i=>i.product).join(' ')).toLowerCase().includes(q))&&(!system||rcSystemKey(o)===system)&&(!status||o.status===status)&&(!payment||o.paymentStatus===payment)&&(!mode||o.paymentMode===mode)&&Number(o.totalEUR||0)>=min&&t>=start&&t<=end&&(!balance||(balance==='yes'?bal>0:balance==='late'?rcIsOverdue(o):bal===0))})}
function rcRefreshOrders(){const rows=rcFilterOrders(),box=$('rcOrderResults');if(box)box.innerHTML=`<div class="${rcOrderView==='systems'?'rc-v10-group':'rc-v10-order-list'}">${rows.length?(rcOrderView==='systems'?rcGroupedOrders(rows):rows.map(rcOrderCard).join('')):'<div class="rc-v10-empty">Aucune commande ne correspond aux filtres.</div>'}</div>`;rcBindDynamic()}
function rcBindDynamic(){document.querySelectorAll('[data-rc-client-sheet]').forEach(b=>b.onclick=()=>rcClientSheet(b.dataset.rcClientSheet));document.querySelectorAll('[data-rc-order-detail]').forEach(b=>b.onclick=()=>{const[tid,i]=b.dataset.rcOrderDetail.split('|');rcShowOrderDetail(tid,Number(i))});document.querySelectorAll('[data-rc-order-status]').forEach(s=>s.onchange=()=>{const[tid,i]=s.dataset.rcOrderStatus.split('|'),o=store.tenants[tid].orders[Number(i)],old=o.status;o.status=s.value;o.statusHistory.unshift({status:o.status,at:new Date().toISOString(),author:adminNameV92()});auditV9('Changement statut commande','commande:'+o.id,old,o.status);saveStore();renderShell()});document.querySelectorAll('[data-rc-payment-status]').forEach(s=>s.onchange=()=>{const[tid,i]=s.dataset.rcPaymentStatus.split('|'),o=store.tenants[tid].orders[Number(i)],old=o.paymentStatus;o.paymentStatus=s.value;if(s.value==='Payé')o.paidAmount=Number(o.totalEUR||0);auditV9('Changement statut paiement','commande:'+o.id,old,o.paymentStatus);saveStore();renderShell()});document.querySelectorAll('[data-rc-filter-system]').forEach(b=>b.onclick=()=>{rcOrderView='orders';const sel=$('rcOrderSystem');if(sel)sel.value=b.dataset.rcFilterSystem;rcRefreshOrders()})}
function rcExportFilteredOrders(){const rows=rcFilterOrders(),data=[['Commande','Date','Client','Entreprise','Système','Total EUR','Encaissé EUR','Remboursé EUR','Solde EUR','Statut commande','Statut paiement','Mode paiement'],...rows.map(x=>[x.order.id,rcDate(x.order.createdAt),rcClientName(x.client),x.client.company,rcSystemKey(x.order),x.order.totalEUR,rcOrderPaid(x.order),rcOrderRefunded(x.order),rcOrderBalance(x.order),x.order.status,x.order.paymentStatus,x.order.paymentMode])],csv=data.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='commandes-renovo-crete.csv';a.click();URL.revokeObjectURL(a.href)}

