const rcBindViewBase=bindView;
bindView=function(){rcBindViewBase();rcBindDynamic();if(currentView==='clients'){const apply=()=>{const q=($('rcClientSearch')?.value||'').toLowerCase(),tier=$('rcClientTier')?.value||'',debt=$('rcClientDebt')?.value||'';document.querySelectorAll('[data-rc-client]').forEach(c=>c.style.display=(!q||c.dataset.search.includes(q))&&(!tier||c.dataset.tier===tier)&&(!debt||c.dataset.debt===debt)?'':'')};['rcClientSearch','rcClientTier','rcClientDebt'].forEach(id=>$(id)?.addEventListener(id==='rcClientSearch'?'input':'change',apply))}if(currentView==='global-orders'){['rcOrderSearch','rcOrderSystem','rcOrderStatus','rcPaymentStatus','rcPaymentMode','rcOrderPeriod','rcOrderStart','rcOrderEnd','rcOrderMin','rcOrderBalance'].forEach(id=>$(id)?.addEventListener(id==='rcOrderSearch'||id==='rcOrderMin'?'input':'change',rcRefreshOrders));document.querySelectorAll('[data-rc-order-view]').forEach(b=>b.onclick=()=>{rcOrderView=b.dataset.rcOrderView;renderShell()});$('rcResetOrders')?.addEventListener('click',()=>renderShell());$('rcExportOrders')?.addEventListener('click',rcExportFilteredOrders);$('rcSaveOrderView')?.addEventListener('click',()=>{store.settings.savedOrderView={system:$('rcOrderSystem').value,status:$('rcOrderStatus').value,payment:$('rcPaymentStatus').value,mode:$('rcPaymentMode').value,period:$('rcOrderPeriod').value,balance:$('rcOrderBalance').value};saveStore();toast('Vue filtrée enregistrée sur cet appareil.')})}if(currentView==='loyalty')$('rcSaveThresholds')?.addEventListener('click',()=>{const premium=Number($('rcPremiumThreshold').value),prestige=Number($('rcPrestigeThreshold').value);if(premium<0||prestige<=premium)return toast('Le seuil Prestige doit être supérieur au seuil Premium.');store.settings.loyaltyThresholds={premium,prestige};rcMigrateV10();renderShell();toast('Seuils de fidélité enregistrés.')});if(currentView==='referrals')$('rcAddReferral')?.addEventListener('click',()=>{const sponsorId=$('rcSponsor').value,referralId=$('rcReferral').value;if(!sponsorId||!referralId||sponsorId===referralId)return toast('Sélectionnez deux clients différents.');store.referrals.unshift({id:'PAR-'+Date.now(),sponsorId,referralId,reward:$('rcReward').value.trim(),status:'En attente de validation',createdAt:new Date().toISOString()});saveStore();renderShell();toast('Parrainage ajouté.')});if(currentView==='system-library'){document.querySelectorAll('[data-rc-use-system]').forEach(b=>b.onclick=()=>{const wanted=b.dataset.rcUseSystem,id=wanted==='uc-48s'?(SYSTEMS.find(s=>/urethane cement/i.test(s.name))?.id||form.systemId):wanted;if(SYSTEMS.some(s=>s.id===id))form.systemId=id;currentView='calculator';result=null;renderShell()});document.querySelectorAll('[data-rc-system-image]').forEach(b=>b.onclick=()=>showModal(`<img src="${esc(b.dataset.rcSystemImage)}" alt="Schéma système" style="width:100%;height:auto"><div class="toolbar"><button class="btn primary" onclick="closeModal()">Fermer</button></div>`))}}
